export const blocks: readonly LiturgyBlock[] = [
  {"id": "cu-sed-0001", "section": "service", "who": "reader", "text": "НА УТРЕНИ"},
  {"id": "cu-sed-0002", "section": "service", "who": "rubric", "text": "Знаменает параекклисиарх к свету, коснее ради вечерняго утешения, и собираемся вси по обычаю в церковь. Поем полунощницу без поклонов, токмо в конец три поклоны великия, с молитвою,"},
  {"id": "cu-sed-0003", "section": "service", "who": "reader", "text": "Господи и Владыко:"},
  {"id": "cu-sed-0004", "section": "service", "who": "rubric", "text": "Сие же бывает в 1-й день токмо. В прочия же дни святаго и великаго поста, поем полунощницу всю с поклоны 16, по обычаю. Таже востав иерей творит обычное метание настоятелю, и входит во святый олтарь, и прием кадильницу, станет пред святою трапезою, и кадя крестообразно, возгласит:"},
  {"id": "cu-sed-0005", "section": "service", "who": "priest", "text": "Благословен Бог наш:"},
  {"id": "cu-sed-0006", "section": "service", "who": "rubric", "text": "И нам отвещавшим:"},
  {"id": "cu-sed-0007", "section": "service", "who": "priest", "text": "Аминь,"},
  {"id": "cu-sed-0008", "section": "service", "who": "rubric", "text": "исходит иерей и кадит. А уставленный псалмопевец глаголет: Трисвятое, всегда кроме метаний. По"},
  {"id": "cu-sed-0009", "section": "service", "who": "priest", "text": "Отче наш,"},
  {"id": "cu-sed-0010", "section": "service", "who": "rubric", "text": "возглашает иерей:"},
  {"id": "cu-sed-0011", "section": "service", "who": "priest", "text": "Яко Твое есть Царство: и по амине,"},
  {"id": "cu-sed-0012", "section": "service", "who": "priest", "text": "Господи помилуй, 12."},
  {"id": "cu-sed-0013", "section": "service", "who": "priest", "text": "Приидите поклонимся:"},
  {"id": "cu-sed-0014", "section": "service", "who": "rubric", "text": "трижды, без метаний. И псалом 19 и 20, по конце их, Трисвятое, без метаний. По"},
  {"id": "cu-sed-0015", "section": "service", "who": "priest", "text": "Отче наш:"},
  {"id": "cu-sed-0016", "section": "service", "who": "rubric", "text": "Тропари обычныя. Сим глаголемым, кадит иерей святый олтарь, и всю церковь. Таже, ектения:"},
  {"id": "cu-sed-0017", "section": "service", "who": "priest", "text": "Помилуй нас Боже: Таже,"},
  {"id": "cu-sed-0018", "section": "service", "who": "priest", "text": "О великом господине и отце нашем Святейшем Патриархе: Возглас:"},
  {"id": "cu-sed-0019", "section": "service", "who": "priest", "text": "Яко милостив и человеколюбец:"},
  {"id": "cu-sed-0020", "section": "service", "who": "reader", "text": "Аминь. И глаголет:"},
  {"id": "cu-sed-0021", "section": "service", "who": "reader", "text": "Именем Господним благослови отче."},
  {"id": "cu-sed-0022", "section": "service", "who": "rubric", "text": "И абие иерей:"},
  {"id": "cu-sed-0023", "section": "service", "who": "priest", "text": "Слава Святей, и Единосущней:"},
  {"id": "cu-sed-0024", "section": "service", "who": "rubric", "text": "И прочая. Брат же, егоже есть день, став на уреченном месте, глаголет шестопсалмие со всяким вниманием, не борзяся, но со страхом Божиим, яко к Самому Богу беседующи невидимо."},
  {"id": "cu-sed-0025", "section": "service", "who": "rubric", "text": "И не имать кто власти шепты творити, ниже плюнути, или хракнути: но паче внимати от псаломника глаголемым, руце имуще согбены к персем, главы же преклонены, и очи имуще долу, сердечныма очима зряще к востоком, да молимся о гресех наших, поминающе смерть, и будущую муку, и жизнь вечную."},
  {"id": "cu-sed-0026", "section": "service", "who": "rubric", "text": "В начало же 102-го псалма, глаголет иерей утренния молитвы. По скончании же псалмов,"},
  {"id": "cu-sed-0027", "section": "service", "who": "priest", "text": "Слава, и ныне, Аллилуия,"},
  {"id": "cu-sed-0028", "section": "service", "who": "rubric", "text": "трижды. Таже, ектения великая, и возглас. Поет же учиненный монах"},
  {"id": "cu-sed-0029", "section": "service", "who": "priest", "text": "Аллилуия,"},
  {"id": "cu-sed-0030", "section": "service", "who": "rubric", "text": "во глас прилучившагося в Октоихе гласа. Стих 1:"},
  {"id": "cu-sed-0031", "section": "service", "who": "priest", "text": "От нощи утренюет дух мой к Тебе Боже, зане свет повеления Твоя. Стих 2:"},
  {"id": "cu-sed-0032", "section": "service", "who": "priest", "text": "Правде научитеся живущии на земли. Стих 3:"},
  {"id": "cu-sed-0033", "section": "service", "who": "priest", "text": "Зависть приимет люди ненаказанныя. Стих 4:"},
  {"id": "cu-sed-0034", "section": "service", "who": "priest", "text": "Приложи им зла Господи, приложи зла славным земли."},
  {"id": "cu-sed-0035", "section": "service", "who": "rubric", "text": "И по коемждо стихе,"},
  {"id": "cu-sed-0036", "section": "service", "who": "priest", "text": "Аллилуия,"},
  {"id": "cu-sed-0037", "section": "service", "who": "rubric", "text": "трижды. Таже Троичны гласа. Поем же со умилением велегласно и косно с пением. На 2-м стихе,"},
  {"id": "cu-sed-0038", "section": "service", "who": "priest", "text": "Слава: а на третием,"},
  {"id": "cu-sed-0039", "section": "service", "who": "priest", "text": "И ныне:"},
  {"id": "cu-sed-0040", "section": "service", "who": "rubric", "text": "Таже стихословим едину кафисму Псалтира. По антифоне же, на"},
  {"id": "cu-sed-0041", "section": "service", "who": "priest", "text": "Аллилуия"},
  {"id": "cu-sed-0042", "section": "service", "who": "rubric", "text": "творим поклоны три, вси равно, последующе игумену, или екклисиарху. По первой кафисме седальны умилительныя Осмогласника."},
  {"id": "cu-sed-0043", "section": "service", "who": "rubric", "text": "Таже чтение во святом Ефреме, зане от того дне начинается святый Ефрем, и чтется до пятка Цветоносныя недели."},
  {"id": "cu-sed-0044", "section": "service", "who": "priest", "text": "По 2-м стихословии седален Триоди господина Иосифа. Глас 2. Подобен: Милосердия сущи:"},
  {"id": "cu-sed-0045", "section": "service", "who": "priest", "text": "Поста Божественным начатком / умиление стяжим, от души вопиюще: / Владыко Христе, молитву нашу приими, яко избранное кадило, / и избави нас, молимся, / злосмрадныя тли, и муки страшныя, / яко един сый благоуветливый."},
  {"id": "cu-sed-0046", "section": "service", "who": "priest", "text": "Слава, тойже."},
  {"id": "cu-sed-0047", "section": "service", "who": "priest", "text": "И ныне, Богородичен. Подобен: Милосердия сущи источник, / милости сподоби нас Богородице, / призри на люди согрешившия, / яви яко присно силу Твою: / на Тя бо уповающе, радуйся вопием Ти, / якоже иногда Гавриил безплотных архистратиг."},
  {"id": "cu-sed-0048", "section": "service", "who": "rubric", "text": "И паки чтение во святем Ефреме."},
  {"id": "cu-sed-0049", "section": "service", "who": "priest", "text": "По 3-м стихословии седален господина Феодора. Глас 2. Подобен: Пречистому Твоему образу:"},
  {"id": "cu-sed-0050", "section": "service", "who": "priest", "text": "Всечестное воздержание начнем светло, / лучами сияюще святых заповедей Христа Бога нашего, / любве светлостию, молитвы блистанием, / чистоты очищением, благомужества крепостию: / яко да светоносни предварим во святое и тридневное Воскресение, / осиявающее нетление миру."},
  {"id": "cu-sed-0051", "section": "service", "who": "priest", "text": "Слава, тойже."},
  {"id": "cu-sed-0052", "section": "service", "who": "priest", "text": "И ныне, Богородичен. Подобен: Необоримую молитву Твою стяжав в лютых, / свобождаюся от оскорбляющих мя паче надежди чудно. / О Мати Божия, предваряеши всегда просящим Тя верно. / Отонудуже благодарно вопием Ти: / приими Владычице, краткая благодарственная, / вместо сих буди ми во всех помощь."},
  {"id": "cu-sed-0053", "section": "service", "who": "rubric", "text": "Таже чтение в Лавсаице. Псалом 50. И обычная молитва:"},
  {"id": "cu-sed-0054", "section": "service", "who": "reader", "text": "Спаси Боже люди Твоя:"},
  {"id": "cu-sed-0055", "section": "service", "who": "rubric", "text": "Таже возглас: Посем начинаем:"},
  {"id": "cu-sed-0056", "section": "service", "who": "reader", "text": "Господеви поем:"},
  {"id": "cu-sed-0057", "section": "service", "who": "rubric", "text": "на глас канона Минеи, дне святаго. И глаголют стихи песней скоро, кийждо лик свой стих: дондеже достигнут до,"},
  {"id": "cu-sed-0058", "section": "service", "who": "reader", "text": "Огустеша:"},
  {"id": "cu-sed-0059", "section": "service", "who": "rubric", "text": "и от того начинают стих держати на 14. И поем Минеи со ирмосом на 6, поем же сице: Первый лик глаголет стих:"},
  {"id": "cu-sed-0060", "section": "service", "who": "choir", "text": "Огустеша:"},
  {"id": "cu-sed-0061", "section": "service", "who": "rubric", "text": "и поет ирмос. Вторый же лик глаголет 2 стих:"},
  {"id": "cu-sed-0062", "section": "service", "who": "choir", "text": "Рече враг:"},
  {"id": "cu-sed-0063", "section": "service", "who": "rubric", "text": "И по нем тропарь канона. И поряду стихи по ликом до,"},
  {"id": "cu-sed-0064", "section": "service", "who": "choir", "text": "Тогда потщашася: от стиха же"},
  {"id": "cu-sed-0065", "section": "service", "who": "choir", "text": "Тогда потщашася,"},
  {"id": "cu-sed-0066", "section": "service", "who": "rubric", "text": "начинаем трипеснец господина Иосифа, на 4. На"},
  {"id": "cu-sed-0067", "section": "service", "who": "choir", "text": "Господь же царствуяй:"},
  {"id": "cu-sed-0068", "section": "service", "who": "rubric", "text": "поем другий трипеснец господина Феодора Студита: и поет 1-й лик тропарь. 2-й же лик 2 стих, и тропарь. Посем соединившимся двум ликом, поют,"},
  {"id": "cu-sed-0069", "section": "service", "who": "choir", "text": "Слава,"},
  {"id": "cu-sed-0070", "section": "service", "who": "rubric", "text": "Троичен, вышшим гласом:"},
  {"id": "cu-sed-0071", "section": "service", "who": "choir", "text": "И ныне,"},
  {"id": "cu-sed-0072", "section": "service", "who": "rubric", "text": "Богородичен. Таже глаголем высочайшим гласом:"},
  {"id": "cu-sed-0073", "section": "service", "who": "choir", "text": "Слава Тебе Боже наш, слава Тебе."},
  {"id": "cu-sed-0074", "section": "service", "who": "rubric", "text": "И поем иный тропарь господина Феодора. Понеже бо по пяти тропарей имать песнь. Последи же глаголем катавасию, ирмос втораго канона."},
  {"id": "cu-sed-0075", "section": "service", "who": "rubric", "text": "Сице поется осмая и девятая песни."},
  {"id": "cu-sed-0076", "section": "service", "who": "rubric", "text": "Третию же песнь поем сице:"},
  {"id": "cu-sed-0077", "section": "service", "who": "rubric", "text": "Глаголет первый лик стих:"},
  {"id": "cu-sed-0078", "section": "service", "who": "choir", "text": "Господь взыде на небеса:"},
  {"id": "cu-sed-0079", "section": "service", "who": "rubric", "text": "и тропарь канона Минеи. Вторый лик стих:"},
  {"id": "cu-sed-0080", "section": "service", "who": "choir", "text": "И даст крепость царю:"},
  {"id": "cu-sed-0081", "section": "service", "who": "rubric", "text": "И вторый тропарь канона Минеи. Таже,"},
  {"id": "cu-sed-0082", "section": "service", "who": "choir", "text": "Слава, и ныне,"},
  {"id": "cu-sed-0083", "section": "service", "who": "rubric", "text": "с тропари канона. И поет первый лик ирмос Минеи третия песни, последи канона."},
  {"id": "cu-sed-0084", "section": "service", "who": "rubric", "text": "Сим образом поем и 6-ю песнь."},
  {"id": "cu-sed-0085", "section": "service", "who": "rubric", "text": "Четвертую же, и пятую, и седмую песни сице поем:"},
  {"id": "cu-sed-0086", "section": "service", "who": "rubric", "text": "Глаголи первее ирмос канона Минеи, таже конечныя два стиха песни поем к тропарем канона: и"},
  {"id": "cu-sed-0087", "section": "service", "who": "choir", "text": "Слава, и ныне,"},
  {"id": "cu-sed-0088", "section": "service", "who": "rubric", "text": "ирмосом же не покрываем песни: зане ирмос глаголется прежде песни. Поются же ирмосы Минеи по каноне, токмо по третией и шестой песнех: занеже у тех песней первее ирмос не поется. В прочия же дни седмицы кроме понедельника, тако поется и 1-я песнь, якоже указася о 4-й, и 5-й, песнех. А в нихже песнех будет трипеснец, поется последи канона катавасия, ирмос трипеснца, якоже вышше изъявися."},
  {"id": "cu-sed-0089", "section": "service", "who": "rubric", "text": "Ведомо же буди: яко Осмогласник не поется во всю святую 40-цу, кроме Недель. Поется же точию Минеа, и трипеснец. А в нихже песнех несть трипеснца, поется токмо Минеа. По 3-й песни глаголет иерей ектению малую. Таже седален святаго единожды."},
  {"id": "cu-sed-0090", "section": "service", "who": "choir", "text": "Слава, и ныне,"},
  {"id": "cu-sed-0091", "section": "service", "who": "rubric", "text": "Богородичен: И чтение в Лавсаице. По 6-й песни ектения малая. Таже седален мученичен: аще же имать святый кондак, глаголем его зде: мученичен же глаголем по 1-й кафисме с седальнами, с припевом:"},
  {"id": "cu-sed-0092", "section": "service", "who": "reader", "text": "Дивен Бог во святых своих:"},
  {"id": "cu-sed-0093", "section": "service", "who": "rubric", "text": "И чтение в Синаксаре."},
  {"id": "cu-sed-0094", "section": "service", "who": "reader", "text": "Канон и трипеснец господина Иосифа. Глас 2: Песнь 1. Ирмос:"},
  {"id": "cu-sed-0095", "section": "service", "who": "reader", "text": "Грядите, людие:"},
  {"id": "cu-sed-0096", "section": "service", "who": "rubric", "text": "Зде стихословится первая песнь."},
  {"id": "cu-sed-0097", "section": "service", "who": "reader", "text": "Како ныне моего восплачу отпадения? / кое начало сотворю спасения моего, блудно поживый, Щедре? / Имиже судьбами веси, спаси мя."},
  {"id": "cu-sed-0098", "section": "service", "who": "reader", "text": "Се время покаяния, се день спасительный, пощения вход: / душе бодрствуй, и страстей входы затвори, / ко Господу взирающи."},
  {"id": "cu-sed-0099", "section": "service", "who": "reader", "text": "Грехов треволнение бурящееся, / во глубину низвлачит мя отчаяния: / но к Твоей прибегаю пучине милости, спаси мя Господи."},
  {"id": "cu-sed-0100", "section": "service", "who": "reader", "text": "Един аз греху поработихся, / един аз страстем двери отверзох, благоуветливе Слове, / обрати мя Спасе благоутробием Твоим. Богородичен:"},
  {"id": "cu-sed-0101", "section": "service", "who": "reader", "text": "Источник безстрастия рождшая, / уязвлена страстьми Отроковице исцели, / и огня вечнаго исхити мя, едина Богоблагодатная."},
  {"id": "cu-sed-0102", "section": "service", "who": "reader", "text": "Иный трипеснец господина Феодора, глас и ирмос тойже:"},
  {"id": "cu-sed-0103", "section": "service", "who": "reader", "text": "Грядите, людие, / днесь восприимем пощений дарование, / яко Богодарованное время покаяния, / в сем Спаса умилостивим."},
  {"id": "cu-sed-0104", "section": "service", "who": "reader", "text": "Приспе ныне, введеся подвигов время, поста поприще / усердно вси начнем сей, / добродетели Господеви яко дары носяще."},
  {"id": "cu-sed-0105", "section": "service", "who": "reader", "text": "Слава, Троичен: Единице простая, трисветлая, начальственнейшая Едина, / всемощнейшая, всежизненная, Боже и Господи, / Отче Вседержителю, Сыне и Душе, спасай чтущия Тя. Богородичен:"},
  {"id": "cu-sed-0106", "section": "service", "who": "reader", "text": "Божию святую гору воспоим, Марию нескверную, / из Неяже возсия правды Солнце, / сущим во тьме Христос, всех Жизнь."},
  {"id": "cu-sed-0107", "section": "service", "who": "reader", "text": "Слава Тебе Боже наш, слава Тебе."},
  {"id": "cu-sed-0108", "section": "service", "who": "reader", "text": "Колесница огненная прият Илию чуднаго, постом вооруженнаго, / Моисея показа зрителя неизреченных: / и мы сей приимше, узрим Христа."},
  {"id": "cu-sed-0109", "section": "service", "who": "reader", "text": "Слава Тебе Боже наш, слава Тебе."},
  {"id": "cu-sed-0110", "section": "service", "who": "reader", "text": "Брашно Адам яде, и от рая того невоздержание изрину: / нас же, Господи пост приемый, / достойны покаяния покажи Человеколюбче. Ирмос:"},
  {"id": "cu-sed-0111", "section": "service", "who": "reader", "text": "Грядите, людие, / поим песнь Христу Богу, / раздельшему море и наставльшему люди, / яже изведе из работы египетския, / яко прославися."},
  {"id": "cu-sed-0112", "section": "service", "who": "rubric", "text": "По 6-й песни мученичен гласа."},
  {"id": "cu-sed-0113", "section": "service", "who": "reader", "text": "Песнь 8. Ирмос:"},
  {"id": "cu-sed-0114", "section": "service", "who": "reader", "text": "В пещь огненную ко отроком еврейским снизшедшаго, / и пламень в росу преложшаго Бога, / пойте дела яко Господа, / и превозносите во вся веки."},
  {"id": "cu-sed-0115", "section": "service", "who": "reader", "text": "Огнесожжена сластьми, и души зрительным помрачена, / огнем Твоего страха обновив Христе, / светом мя спасения озари, да Тя славлю во вся веки."},
  {"id": "cu-sed-0116", "section": "service", "who": "reader", "text": "Сытость возненавидевши страстей, / напитайся добрых сладостною пищею, / и усладися паче от поста сладостию, / горести сластей уклоняющися, смиренная душе моя, / и поживи во веки."},
  {"id": "cu-sed-0117", "section": "service", "who": "reader", "text": "Ослеплен душею, и пиянством страстей отемнен, / никакоже взираю к Тебе Единому Богу. / Темже мя ущедри и просвети, / и покаяния отверзи ми врата. Богородичен:"},
  {"id": "cu-sed-0118", "section": "service", "who": "reader", "text": "Онебесившая наше земное и тленное Чистая, существо, / теплою Твоею молитвою, управитися нашим мольбам и молениям сотвори, / к Твоему и всех Богу, и Царю."},
  {"id": "cu-sed-0119", "section": "service", "who": "reader", "text": "Иный. Ирмос:"},
  {"id": "cu-sed-0120", "section": "service", "who": "reader", "text": "Древле оросившаго:"},
  {"id": "cu-sed-0121", "section": "service", "who": "reader", "text": "Светло усрящим поста вход вернии, и да не сетуим: / но омыим лица наша безстрастия водою, / благословяще и превозносяще Христа во веки."},
  {"id": "cu-sed-0122", "section": "service", "who": "reader", "text": "Елеем помазавше милости души главу, / не многословим Отцу нашему, Сущему на Небесех, / молитвы возсылающе, / благословяще и превозносяще Его во вся веки."},
  {"id": "cu-sed-0123", "section": "service", "who": "reader", "text": "Благословим Отца и Сына, и Святаго Духа, Господа."},
  {"id": "cu-sed-0124", "section": "service", "who": "reader", "text": "Присносущна, безначальна Отца, воспоим вернии, / Сына же собезначальна, и Духа сопросиявша из Отца, / единосущна Лица, / Единаго суща всесильнаго начала и власти."},
  {"id": "cu-sed-0125", "section": "service", "who": "reader", "text": "И ныне и присно, и во веки веков, аминь. Богородичен:"},
  {"id": "cu-sed-0126", "section": "service", "who": "reader", "text": "Марие Богозванная, очистилище воистинну верных, / из Тебе бо оставление подавается всем богатно: / Сына Твоего и Господа не престай молящи о поющих Тя."},
  {"id": "cu-sed-0127", "section": "service", "who": "reader", "text": "Слава Тебе Боже наш, слава Тебе."},
  {"id": "cu-sed-0128", "section": "service", "who": "reader", "text": "Постився Господь четыредесятную меру дней, / сия ныне освяти и очисти дни, братие, в няже достигше, зовем: / благословите, и превозносите Христа во веки."},
  {"id": "cu-sed-0129", "section": "service", "who": "reader", "text": "Хвалим, благословим, покланяемся Господеви, поюще, и превозносяще во вся веки. Ирмос:"},
  {"id": "cu-sed-0130", "section": "service", "who": "reader", "text": "Древле оросившаго еврейския отроки в пламени, / и опалившаго Господа халдеи преславно в нем, / воспоем, глаголюще: / благословите, и превозносите Его во веки."},
  {"id": "cu-sed-0131", "section": "service", "who": "rubric", "text": "И стихословится"},
  {"id": "cu-sed-0132", "section": "service", "who": "reader", "text": "Честнейшую:"},
  {"id": "cu-sed-0133", "section": "service", "who": "reader", "text": "Песнь 9. Ирмос:"},
  {"id": "cu-sed-0134", "section": "service", "who": "reader", "text": "От Бога Бога Слова, / неизреченною мудростию пришедшего обновите Адама, / ядию в тление падшаго люте, / от Святыя Девы неизреченно воплотившагося нас ради, / вернии, единомудренно песньми величаем."},
  {"id": "cu-sed-0135", "section": "service", "who": "reader", "text": "Поста день, отложение греха да будет ти душе, / и к Богу мание вкупе, и присвоение: / яко да убежиши злобныя пропасти, / и самыя токмо пути возлюбиши, ведущия ко оному покою."},
  {"id": "cu-sed-0136", "section": "service", "who": "reader", "text": "И помышленьми поползнувся, / и плотию прегрешив рыдаю, и стеню, и вопию: / спаси мя Господи, спаси мя незлобиве едине, / и не осуди мене во огнь геенны оныя, осуждения достойнаго."},
  {"id": "cu-sed-0137", "section": "service", "who": "reader", "text": "Во светлую поста облекшеся ризу, / пиянства темныя и злотяжкия совлецемся одежды, / и светли бывше Божественными добродетельми, / светозарная Спасова верою узрим страдания. Богородичен:"},
  {"id": "cu-sed-0138", "section": "service", "who": "reader", "text": "Изнемогшую всеми прилоги злобных бесов, / страстную мою душу исцели Пречистая Владычице, / Целителя рождшая Христа, избавление нас, / ведущих Тя Отроковицу, Деву нетленну."},
  {"id": "cu-sed-0139", "section": "service", "who": "reader", "text": "Иный. Ирмос:с:"},
  {"id": "cu-sed-0140", "section": "service", "who": "reader", "text": "Преестественно:"},
  {"id": "cu-sed-0141", "section": "service", "who": "reader", "text": "Ныне наста время святых постов, / начнем сего в добрых пребываниих: / в судах бо и крамолах не поститеся глаголет."},
  {"id": "cu-sed-0142", "section": "service", "who": "reader", "text": "В горе Хорив постом очищься, виде Бога Илия: / очистим и мы постом сердце, и узрим Христа."},
  {"id": "cu-sed-0143", "section": "service", "who": "reader", "text": "Слава, Троичен: Единому Естеству покланяюся, три Лица пою, / Единаго Бога всех, / Отца, и Сына, и Святаго Духа, присносущное начало. Богородичен:"},
  {"id": "cu-sed-0144", "section": "service", "who": "reader", "text": "Чистая Отроча раждаеши, Дева млеком доиши: / како в сию двою девствуеши рождши? / Бог есть содеявый, не взыскуй от Мене, еже како?"},
  {"id": "cu-sed-0145", "section": "service", "who": "reader", "text": "Слава Тебе Боже наш, слава Тебе."},
  {"id": "cu-sed-0146", "section": "service", "who": "reader", "text": "День един убо, рече, житие всяко земных: / труждающимся от любве четыредесять суть дней поста, / яже совершим светло. Ирмос:"},
  {"id": "cu-sed-0147", "section": "service", "who": "reader", "text": "Преестественно плотию заченшую во чреве, / от Отца безлетно предвозсиявшее Слово, / в песнех немолчных / величаем, вернии. Таже,"},
  {"id": "cu-sed-0148", "section": "service", "who": "reader", "text": "Достойно есть:"},
  {"id": "cu-sed-0149", "section": "service", "who": "rubric", "text": "Поклон един. ектения:"},
  {"id": "cu-sed-0150", "section": "service", "who": "reader", "text": "Паки, и паки:"},
  {"id": "cu-sed-0151", "section": "service", "who": "rubric", "text": "И светилен Троичен гласа. На"},
  {"id": "cu-sed-0152", "section": "service", "who": "reader", "text": "Всякое дыхание"},
  {"id": "cu-sed-0153", "section": "service", "who": "rubric", "text": "стихов не поем, но стихологисуем:"},
  {"id": "cu-sed-0154", "section": "service", "who": "reader", "text": "Хвалите Господа с Небес:"},
  {"id": "cu-sed-0155", "section": "service", "who": "rubric", "text": "обычныя псалмы, 3. И аще прилучится в Минеи на ряду два святых: Поем единому вечер стихиры, а другому на Хвалитех стихиры на 4, аще будут. Аще же ни, глаголет учиненный брат:"},
  {"id": "cu-sed-0156", "section": "service", "who": "reader", "text": "Тебе слава подобает Господи Боже наш, и Тебе славу возсылаем, Отцу, и Сыну, и Святому Духу, ныне и присно, и во веки веков, аминь. Слава Тебе, показавшему нам свет. Слава в вышних Богу:"},
  {"id": "cu-sed-0157", "section": "service", "who": "rubric", "text": "И прочая. И творим метания 3, равно на местех наших стояще. Посем иерей:"},
  {"id": "cu-sed-0158", "section": "service", "who": "priest", "text": "Исполним утреннюю: И возглас."},
  {"id": "cu-sed-0159", "section": "service", "who": "rubric", "text": "И совокупльшеся оба лика вкупе, поем:"},
  {"id": "cu-sed-0160", "section": "service", "who": "choir", "text": "На стиховне самогласен, глас 5:"},
  {"id": "cu-sed-0161", "section": "service", "who": "choir", "text": "Прииде пост, мати целомудрия, / обличитель грехов, проповедник покаяния, / жительство ангелов, и спасение человеков, / вернии возопиим: Боже, помилуй нас. Стих:"},
  {"id": "cu-sed-0162", "section": "service", "who": "choir", "text": "Исполнихомся заутра милости Твоея, Господи, возрадовахомся, и возвеселихомся: во вся дни наша возвеселихомся. За дни, в няже смирил ны еси, лета в няже видехом злая. И призри на рабы Твоя, и на дела Твоя, / и настави сыны их."},
  {"id": "cu-sed-0163", "section": "service", "who": "rubric", "text": "И повторяем тойже."},
  {"id": "cu-sed-0164", "section": "service", "who": "rubric", "text": "Таже стих:"},
  {"id": "cu-sed-0165", "section": "service", "who": "choir", "text": "И буди светлость Господа Бога нашего на нас, и дела рук наших исправи на нас, / и дело рук наших исправи. И мученичен:"},
  {"id": "cu-sed-0166", "section": "service", "who": "choir", "text": "Благословено воинство Царя Небеснаго, / аще бо и земнороднии быша страстотерпцы, / но ангельский сан потщашася достигнути, о телесех небрегше, / и страстьми своими безплотных чести сподобишася: / молитвами их, Господи спаси души наша."},
  {"id": "cu-sed-0167", "section": "service", "who": "choir", "text": "Слава, и ныне, Богородичен: Тя Божию Матерь, Деву Чистую и херувим святейшую, / во гласех песней величаем: / зане душею и телом Богородицу исповедуем, / яко воистинну рождшую Бога воплощенна: / молися Пречистая о душах наших. Таже,"},
  {"id": "cu-sed-0168", "section": "service", "who": "choir", "text": "Благо есть:"},
  {"id": "cu-sed-0169", "section": "service", "who": "rubric", "text": "дважды. Трисвятое, и метания 3."},
  {"id": "cu-sed-0170", "section": "service", "who": "choir", "text": "Пресвятая Троице: Отче наш:"},
  {"id": "cu-sed-0171", "section": "service", "who": "rubric", "text": "По внегда же рещи иерею:"},
  {"id": "cu-sed-0172", "section": "service", "who": "choir", "text": "Яко Твое есть Царство:"},
  {"id": "cu-sed-0173", "section": "service", "who": "rubric", "text": "глаголем тропарь:"},
  {"id": "cu-sed-0174", "section": "service", "who": "choir", "text": "В храме стояще славы Твоея: И глаголем,"},
  {"id": "cu-sed-0175", "section": "service", "who": "choir", "text": "Господи помилуй,"},
  {"id": "cu-sed-0176", "section": "service", "who": "rubric", "text": "40. Таже отходит священник, и глаголет:"},
  {"id": "cu-sed-0177", "section": "service", "who": "priest", "text": "Сый благословен Христос Бог наш: Небесный Царю:"},
  {"id": "cu-sed-0178", "section": "service", "who": "rubric", "text": "Посем же стоим, и молимся в себе, во своем помышлении глаголюще молитву преподобнаго отца нашего Ефрема:"},
  {"id": "cu-sed-0179", "section": "service", "who": "priest", "text": "Господи и Владыко живота моего:"},
  {"id": "cu-sed-0180", "section": "service", "who": "rubric", "text": "И поклоны великия 3: и малых 12, глаголюще в себе на едином коемждо:"},
  {"id": "cu-sed-0181", "section": "service", "who": "choir", "text": "Боже, очисти мя грешнаго."},
  {"id": "cu-sed-0182", "section": "service", "who": "rubric", "text": "Таже паки ин поклон великий един, глаголюще и в нем предписанную молитву всю святаго Ефрема. И по еже востати нам, начинает предстоятель:"},
  {"id": "cu-sed-0183", "section": "service", "who": "choir", "text": "Приидите поклонимся:"},
  {"id": "cu-sed-0184", "section": "service", "who": "rubric", "text": "трижды, и метания три. И совокупляем первый час. И скончану третиему псалму, глаголем"},
  {"id": "cu-sed-0185", "section": "service", "who": "choir", "text": "Аллилуия,"},
  {"id": "cu-sed-0186", "section": "service", "who": "rubric", "text": "и метания три."},
  {"id": "cu-sed-0187", "section": "service", "who": "rubric", "text": "Подобает ведати: яко во вся понедельники святыя Четыредесятницы на 1-м часе кафисмы не стихословим. В прочия же дни, стихословим кафисму, и творим на коемждо антифоне метания три."},
  {"id": "cu-sed-0188", "section": "service", "who": "rubric", "text": "Такожде и в пяток, первый час и девятый, без кафисмы. Поет же учиненный чтец, или иерей, среди церкве тропарь, на глас 6:"},
  {"id": "cu-sed-0189", "section": "service", "who": "priest", "text": "Заутра услыши глас мой:"},
  {"id": "cu-sed-0190", "section": "service", "who": "rubric", "text": "И мы поем велегласно тожде, и творим коленоприклонение на землю. Такожде и на прочия два стиха. Стих 1:"},
  {"id": "cu-sed-0191", "section": "service", "who": "priest", "text": "Глаголы моя внуши Господи, разумей звание мое. Стих 2:"},
  {"id": "cu-sed-0192", "section": "service", "who": "priest", "text": "Яко к Тебе помолюся Господи. И паки:"},
  {"id": "cu-sed-0193", "section": "service", "who": "priest", "text": "Заутра услыши глас мой:"},
  {"id": "cu-sed-0194", "section": "service", "who": "rubric", "text": "Слава, и ныне:"},
  {"id": "cu-sed-0195", "section": "service", "who": "priest", "text": "Что Тя наречем, о Благодатная,"},
  {"id": "cu-sed-0196", "section": "service", "who": "rubric", "text": "И метания 3. Таже:"},
  {"id": "cu-sed-0197", "section": "service", "who": "priest", "text": "Стопы моя направи по словеси Твоему, и да не обладает мною всякое беззаконие."},
  {"id": "cu-sed-0198", "section": "service", "who": "rubric", "text": "И повторяем тойжде. Таже:"},
  {"id": "cu-sed-0199", "section": "service", "who": "priest", "text": "Избави мя от клеветы человеческия, и сохраню заповеди Твоя. Паки тойжде:"},
  {"id": "cu-sed-0200", "section": "service", "who": "priest", "text": "Лице Твое просвети на раба Твоего, и научи мя оправданием Твоим."},
  {"id": "cu-sed-0201", "section": "service", "who": "rubric", "text": "Паки тойжде. Сие же глаголем трижды, велегласно и косно."},
  {"id": "cu-sed-0202", "section": "service", "who": "priest", "text": "Да исполнятся уста моя хваления Твоего Господи:"},
  {"id": "cu-sed-0203", "section": "service", "who": "rubric", "text": "Трисвятое. И метания три."},
  {"id": "cu-sed-0204", "section": "service", "who": "priest", "text": "Пресвятая Троице: Отче наш:"},
  {"id": "cu-sed-0205", "section": "service", "who": "rubric", "text": "Возглашает священник:"},
  {"id": "cu-sed-0206", "section": "service", "who": "priest", "text": "Яко Твое есть Царство:"},
  {"id": "cu-sed-0207", "section": "service", "who": "rubric", "text": "И по амине глаголем тропарь. В понедельник убо, и во вторник, и четверток, глаголи Богородичен:"},
  {"id": "cu-sed-0208", "section": "service", "who": "priest", "text": "Преславную Божию Матерь:"},
  {"id": "cu-sed-0209", "section": "service", "who": "rubric", "text": "В среду же и пяток глаголи:"},
  {"id": "cu-sed-0210", "section": "service", "who": "priest", "text": "Скоро предвари, прежде даже не поработимся: Господи помилуй,"},
  {"id": "cu-sed-0211", "section": "service", "who": "rubric", "text": "И глаголем молитву:"},
  {"id": "cu-sed-0212", "section": "service", "who": "priest", "text": "Иже на всякое время: Господи помилуй,"},
  {"id": "cu-sed-0213", "section": "service", "who": "rubric", "text": "трижды. Слава, и ныне,"},
  {"id": "cu-sed-0214", "section": "service", "who": "priest", "text": "Честнейшую херувим:"},
  {"id": "cu-sed-0215", "section": "service", "who": "rubric", "text": "И поклон един."},
  {"id": "cu-sed-0216", "section": "service", "who": "priest", "text": "Именем Господним благослови отче."},
  {"id": "cu-sed-0217", "section": "service", "who": "priest", "text": "Боже, ущедри ны, и благослови ны, просвети лице Твое на ны, и помилуй ны."},
  {"id": "cu-sed-0218", "section": "service", "who": "rubric", "text": "И творим поклоны, якоже предписася: и потом глаголет предстоятель, или чтец: Трисвятое, и метания три."},
  {"id": "cu-sed-0219", "section": "service", "who": "priest", "text": "Отче наш: Господи помилуй,"},
  {"id": "cu-sed-0220", "section": "service", "who": "rubric", "text": "40. И молитва,"},
  {"id": "cu-sed-0221", "section": "service", "who": "priest", "text": "Христе Свете истинный:"},
  {"id": "cu-sed-0222", "section": "service", "who": "priest", "text": "Слава Тебе Христе Боже, упование наше слава Тебе. Мы же,"},
  {"id": "cu-sed-0223", "section": "service", "who": "priest", "text": "Слава, и ныне: Господи помилуй, трижды."},
  {"id": "cu-sed-0224", "section": "service", "who": "priest", "text": "Благослови."},
  {"id": "cu-sed-0225", "section": "service", "who": "rubric", "text": "И отпуст. Таже, Многолетное. И целуем святыя иконы."},
  {"id": "cu-sed-0226", "section": "service", "who": "rubric", "text": "Таже исходим, литию творяще в притворе."},
  {"id": "cu-sed-0227", "section": "service", "who": "rubric", "text": "И тамо глаголются обычныя молитвы: и чтутся оглашения преподобнаго отца нашего Феодора Студита от предстоятеля, или от екклисиарха, яко преписася, сиречь, в среду и пяток."},
  {"id": "cu-sed-0228", "section": "service", "who": "rubric", "text": "И бывает конец, и отпуст."},
  {"id": "cu-sed-0229", "section": "service", "who": "rubric", "text": "Сей образ бывает во святую Четыредесятницу на Утрени, и на первом часе. По отпущении же исходяще из церкве, идем со всяким безмолвием в келлии своя, или на службу: и не подобает нам беседы творити друг со другом на монастыре в пути, удержано бо бысть сие от святых отец."},
  {"id": "cu-sed-0230", "section": "service", "who": "priest", "text": "ОБ ТРЕТИЕМ ЖЕ ЧАСЕ:"},
  {"id": "cu-sed-0231", "section": "service", "who": "rubric", "text": "Ударяет кандиловжигатель в било довольно: И собираемся в церковь, творяще прежде начала пения кийждо нас пред святыми дверьми поклоны 3 и целуем святыя иконы. И на оба лика по единому малу поклону. Благословившу же священнику, И начинающим нам:"},
  {"id": "cu-sed-0232", "section": "service", "who": "priest", "text": "Царю Небесный:"},
  {"id": "cu-sed-0233", "section": "service", "who": "rubric", "text": "Трисвятое. И метания 3. По"},
  {"id": "cu-sed-0234", "section": "service", "who": "priest", "text": "Отче наш:"},
  {"id": "cu-sed-0235", "section": "service", "who": "priest", "text": "Яко Твое есть Царство: И по амине,"},
  {"id": "cu-sed-0236", "section": "service", "who": "priest", "text": "Господи помилуй, 12."},
  {"id": "cu-sed-0237", "section": "service", "who": "priest", "text": "Приидите поклонимся:"},
  {"id": "cu-sed-0238", "section": "service", "who": "rubric", "text": "трижды и метания 3. И стихословится третий час, якоже обычай."},
  {"id": "cu-sed-0239", "section": "service", "who": "rubric", "text": "В конце же третияго псалма, на"},
  {"id": "cu-sed-0240", "section": "service", "who": "priest", "text": "Аллилуия"},
  {"id": "cu-sed-0241", "section": "service", "who": "rubric", "text": "метания три. И стихословим кафисму рядовую: на коемждо же антифоне творим метания три. И по кафисме чтец, или иерей, став среди церкве, глаголет тропарь, глас 6:"},
  {"id": "cu-sed-0242", "section": "service", "who": "priest", "text": "Господи, иже Пресвятаго Твоего Духа:"},
  {"id": "cu-sed-0243", "section": "service", "who": "rubric", "text": "И нам противоглашающим, творим коленоприклонение до земли. Такожде и на прочия два стиха. Стих:"},
  {"id": "cu-sed-0244", "section": "service", "who": "priest", "text": "Сердце чисто созижди во мне Боже, и дух прав обнови во утробе моей. Стих:"},
  {"id": "cu-sed-0245", "section": "service", "who": "priest", "text": "Не отвержи мене от лица Твоего, и Духа Твоего Святаго не отыми от мене. Слава, и ныне,"},
  {"id": "cu-sed-0246", "section": "service", "who": "rubric", "text": "Богородичен: и метания три,"},
  {"id": "cu-sed-0247", "section": "service", "who": "priest", "text": "Богородице, Ты еси лоза истинная:"},
  {"id": "cu-sed-0248", "section": "service", "who": "rubric", "text": "И абие чтем в Лествичнике. Начинает же от ныне учиненный монах возбуждати братию, во всю святую 40-цу: обходит же тихо, и призирает на спящия, и возставляет к слышанию, по последовавшему образу. По чтении же,"},
  {"id": "cu-sed-0249", "section": "service", "who": "priest", "text": "Господь Бог благословен:"},
  {"id": "cu-sed-0250", "section": "service", "who": "rubric", "text": "Трисвятое. и метания три. И по"},
  {"id": "cu-sed-0251", "section": "service", "who": "priest", "text": "Отче наш:"},
  {"id": "cu-sed-0252", "section": "service", "who": "rubric", "text": "Возглашает священник:"},
  {"id": "cu-sed-0253", "section": "service", "who": "priest", "text": "Яко Твое есть Царство:"},
  {"id": "cu-sed-0254", "section": "service", "who": "rubric", "text": "И по амине поем тропари на глас 8:"},
  {"id": "cu-sed-0255", "section": "service", "who": "priest", "text": "Благословен еси Христе Боже наш: Слава: Скорое и известное даждь утешение: И ныне: Надежда и предстательство: Господи помилуй,"},
  {"id": "cu-sed-0256", "section": "service", "who": "rubric", "text": "40. И молитва,"},
  {"id": "cu-sed-0257", "section": "service", "who": "priest", "text": "Иже на всякое время: Господи помилуй, трижды."},
  {"id": "cu-sed-0258", "section": "service", "who": "priest", "text": "Слава, и ныне: Честнейшую херувим: Именем Господним благослови отче:"},
  {"id": "cu-sed-0259", "section": "service", "who": "rubric", "text": "И священник:"},
  {"id": "cu-sed-0260", "section": "service", "who": "priest", "text": "Боже ущедри ны:"},
  {"id": "cu-sed-0261", "section": "service", "who": "rubric", "text": "Творим поклоны, якоже предписася, глаголет предстоятель молитву:"},
  {"id": "cu-sed-0262", "section": "service", "who": "priest", "text": "Владыко Боже Отче Вседержителю:"},
  {"id": "cu-sed-0263", "section": "service", "who": "priest", "text": "НА ШЕСТОМ ЧАСЕ"},
  {"id": "cu-sed-0264", "section": "service", "who": "rubric", "text": "Кандиловжигатель же сотворив обычный поклон предстоятелю, отходит и ударяет в било шесть крат. И по исполнении молитвы,"},
  {"id": "cu-sed-0265", "section": "service", "who": "priest", "text": "Приидите поклонимся:"},
  {"id": "cu-sed-0266", "section": "service", "who": "rubric", "text": "трижды. И метания три. И стихословим шестый час. И по конце,"},
  {"id": "cu-sed-0267", "section": "service", "who": "priest", "text": "Слава, и ныне, Аллилуия,"},
  {"id": "cu-sed-0268", "section": "service", "who": "rubric", "text": "трижды. и метания три. И стихословим кафисму, и по коемждо антифоне,"},
  {"id": "cu-sed-0269", "section": "service", "who": "priest", "text": "Аллилуия"},
  {"id": "cu-sed-0270", "section": "service", "who": "rubric", "text": "трижды: и метания 3. По стихословии же тропарь, глас 2:"},
  {"id": "cu-sed-0271", "section": "service", "who": "priest", "text": "Иже в шестый день же и час: Стих 1:"},
  {"id": "cu-sed-0272", "section": "service", "who": "priest", "text": "Внуши Боже молитву мою, и не презри моления моего. Стих 2:"},
  {"id": "cu-sed-0273", "section": "service", "who": "priest", "text": "Аз к Богу воззвах, и Господь услыша мя."},
  {"id": "cu-sed-0274", "section": "service", "who": "rubric", "text": "Творяще и поклоны 3, яко предписася."},
  {"id": "cu-sed-0275", "section": "service", "who": "priest", "text": "Слава, и ныне, Яко не имамы дерзновения:"},
  {"id": "cu-sed-0276", "section": "service", "who": "rubric", "text": "и метания три."},
  {"id": "cu-sed-0277", "section": "service", "who": "priest", "text": "Таже поем тропарь пророчества, глас 5:"},
  {"id": "cu-sed-0278", "section": "service", "who": "priest", "text": "Господи Господи, / Егоже вся ужасаются и трепещут от лица силы Твоея, / Тебе припадаем безсмертне, Тебе молимся Святый: / спаси души наша, молитвами святых Твоих."},
  {"id": "cu-sed-0279", "section": "service", "who": "priest", "text": "Слава, и ныне:"},
  {"id": "cu-sed-0280", "section": "service", "who": "rubric", "text": "и повторяем тойжде."},
  {"id": "cu-sed-0281", "section": "service", "who": "priest", "text": "Прокимен, глас 4, псалом 1:"},
  {"id": "cu-sed-0282", "section": "service", "who": "priest", "text": "Весть Господь путь праведных, / и путь нечестивых погибнет. Стих:"},
  {"id": "cu-sed-0283", "section": "service", "who": "priest", "text": "Блажен муж, иже не иде на совет нечестивых, и на пути грешных не ста."},
  {"id": "cu-sed-0284", "section": "service", "who": "priest", "text": "Пророчества Исаиина чтение. [Глава 1, ст. 1 – 20.]"},
  {"id": "cu-sed-0285", "section": "service", "who": "priest", "text": "Видение, еже виде Исаия сын Амосов, еже виде на Иудею, и на Иерусалим, в царство Озии и Иофама, и Ахаза и Езекии, иже царствоваша во Иудеи. Слыши небо, и внуши земле, яко Господь возглагола: сыны родих и возвысих, тии же отвергошася Мене. Позна вол стяжавшаго и, и осел ясли господина своего. Израиль же Мене не позна, и людие Мои не разумеша. Увы язык грешный, людие исполнени грехов, семя лукавое сынове беззаконнии, остависте Господа, и разгневасте Святаго Израилева: отвратистеся вспять. Что еще уязвляетеся, прилагающе беззаконие? Всякая глава в болезнь, и всякое сердце в печаль. От ног даже до главы несть в нем целости: ни струп, ни язва, ни рана палящаяся: несть пластыря приложити, ниже елея, ниже обязания. Земля ваша пуста, гради ваши огнем пожжени, страну вашу пред вами чуждии поядают, и опусте низвращенна от людей чуждих. Оставится дщерь Сионя, яко куща в винограде, и яко овощное хранилище в вертограде, яко град воюемый: аще не бы Господь Саваоф оставил нам семене, яко Содома убо были быхом, и яко Гоморру уподобилися быхом. Услышите слово Господне, князи Содомстии: внемлите закону Божию, людие Гоморрстии. Что ми множество жертв ваших? – глаголет Господь. Исполнен есмь всесожжений овних и тука агнцов, и крове юнцов и козлов не хощу. Ниже приходите явитися Ми: кто бо изыска сия из рук ваших? Ходити по двору Моему не приложите. И аще принесете Ми семидал, всуе: кадило, мерзость Ми есть. Новомесячий ваших, и суббот, и дне великаго не потерплю: поста, и праздности, и новомесячий ваших, и праздников ваших ненавидит душа Моя: бысте ми в сытость, ктому не стерплю грехов ваших. Егда прострете руки [ваша] ко Мне, отвращу очи Мои от вас: и аще умножите моление, не услышу вас: руки бо ваша исполнены крове. Измыйтеся, [и] чисти будите, отымите лукавства от душ ваших пред очима Моима, престаните от лукавств ваших. Научитеся добро творити, взыщите суда, избавите обидимаго, судите сиру, и оправдите вдовицу. И приидите, и истяжимся, глаголет Господь. И аще будут греси ваши яко багряное, яко снег убелю; аще же будут яко червленое, яко волну убелю. И аще хощете, и послушаете Мене, благая земли снесте. Аще же не хощете, ниже послушаете Мене, меч вы пояст: уста бо Господня глаголаша сия."},
  {"id": "cu-sed-0286", "section": "service", "who": "priest", "text": "Прокимен, глас 7. псалом 2:"},
  {"id": "cu-sed-0287", "section": "service", "who": "priest", "text": "Работайте Господеви со страхом, / и радуйтеся Ему с трепетом. Стих:"},
  {"id": "cu-sed-0288", "section": "service", "who": "priest", "text": "Вскую шаташася языцы, и людие поучишася тщетным?"},
  {"id": "cu-sed-0289", "section": "service", "who": "rubric", "text": "И бывает чтение в Лествичнике. Таже тропарь:"},
  {"id": "cu-sed-0290", "section": "service", "who": "reader", "text": "Скоро да предварят ны:"},
  {"id": "cu-sed-0291", "section": "service", "who": "rubric", "text": "Трисвятое. И метания 3. По"},
  {"id": "cu-sed-0292", "section": "service", "who": "reader", "text": "Отче наш:"},
  {"id": "cu-sed-0293", "section": "service", "who": "rubric", "text": "иерей, возглас:"},
  {"id": "cu-sed-0294", "section": "service", "who": "priest", "text": "Яко Твое есть Царство:"},
  {"id": "cu-sed-0295", "section": "service", "who": "rubric", "text": "И тропари на глас 2:"},
  {"id": "cu-sed-0296", "section": "service", "who": "priest", "text": "Спасение соделал еси: Слава: Пречистому образу Твоему: И ныне: Милосердия сущи:"},
  {"id": "cu-sed-0297", "section": "service", "who": "rubric", "text": "В среду же и пяток глаголем Крестобогородичен:"},
  {"id": "cu-sed-0298", "section": "service", "who": "priest", "text": "Препрославлена еси Богородице Дево: Господи помилуй, 40."},
  {"id": "cu-sed-0299", "section": "service", "who": "priest", "text": "Иже на всякое время: Господи помилуй, трижды."},
  {"id": "cu-sed-0300", "section": "service", "who": "priest", "text": "Слава, и ныне: Честнейшую херувим: Именем Господним благослови отче."},
  {"id": "cu-sed-0301", "section": "service", "who": "priest", "text": "Боже, ущедри ны и благослови ны:"},
  {"id": "cu-sed-0302", "section": "service", "who": "rubric", "text": "И творим поклоны, якоже обычай. И по исполнении поклонов начинает предстоятель конечное Трисвятое, и метания три. По"},
  {"id": "cu-sed-0303", "section": "service", "who": "priest", "text": "Отче наш: Господи помилуй,"},
  {"id": "cu-sed-0304", "section": "service", "who": "rubric", "text": "12. Таже иерей:"},
  {"id": "cu-sed-0305", "section": "service", "who": "priest", "text": "Слава Тебе Христе Боже, упование наше, слава Тебе."},
  {"id": "cu-sed-0306", "section": "service", "who": "rubric", "text": "И бывает отпуст."},
  {"id": "cu-sed-0307", "section": "service", "who": "rubric", "text": "Сей образ и чин должен быти во всю святую Четыредесятницу, на 3-м и на 6-м часе. А идеже расхода не бывает, по молитве:"},
  {"id": "cu-sed-0308", "section": "service", "who": "priest", "text": "Боже и Господи сил:"},
  {"id": "cu-sed-0309", "section": "service", "who": "rubric", "text": "абие глаголем:"},
  {"id": "cu-sed-0310", "section": "service", "who": "priest", "text": "Приидите поклонимся:"},
  {"id": "cu-sed-0311", "section": "service", "who": "rubric", "text": "трижды, и 9-й час. А идеже бывает расход, о часе 9-м биет кандиловжигатель девятищи, и собираемся в церковь. И благословившу иерею, начинаем Трисвятое, и метания три. По"},
  {"id": "cu-sed-0312", "section": "service", "who": "priest", "text": "Отче наш:"},
  {"id": "cu-sed-0313", "section": "service", "who": "rubric", "text": "Возглашает священник:"},
  {"id": "cu-sed-0314", "section": "service", "who": "priest", "text": "Яко твое есть Царство: И по амине,"},
  {"id": "cu-sed-0315", "section": "service", "who": "priest", "text": "Господи помилуй, 12."},
  {"id": "cu-sed-0316", "section": "service", "who": "priest", "text": "Приидите поклонимся:"},
  {"id": "cu-sed-0317", "section": "service", "who": "rubric", "text": "трижды, и метания три, и поем час девятый трипсалмный. В конец же третияго псалма, на"},
  {"id": "cu-sed-0318", "section": "service", "who": "priest", "text": "Аллилуия,"},
  {"id": "cu-sed-0319", "section": "service", "who": "rubric", "text": "метания три. И начинаем стихословие кафисмы: На всякий же антифон метания три."},
  {"id": "cu-sed-0320", "section": "service", "who": "rubric", "text": "По исполнении же стихословия тропарь, глас 8:"},
  {"id": "cu-sed-0321", "section": "service", "who": "priest", "text": "Иже в девятый час: Стих 1:"},
  {"id": "cu-sed-0322", "section": "service", "who": "priest", "text": "Да приближится молитва моя пред Тя Господи: Стих 2:"},
  {"id": "cu-sed-0323", "section": "service", "who": "priest", "text": "Да внидет прошение мое:"},
  {"id": "cu-sed-0324", "section": "service", "who": "rubric", "text": "И творяще поклоны в сих."},
  {"id": "cu-sed-0325", "section": "service", "who": "priest", "text": "Слава, и ныне: Иже нас ради рождейся от Девы:"},
  {"id": "cu-sed-0326", "section": "service", "who": "rubric", "text": "метания три. И бывает чтение паки в Лествичнике. И по чтении глаголем стих:"},
  {"id": "cu-sed-0327", "section": "service", "who": "reader", "text": "Не предаждь нас до конца:"},
  {"id": "cu-sed-0328", "section": "service", "who": "rubric", "text": "Трисвятое, и метания три."},
  {"id": "cu-sed-0329", "section": "service", "who": "reader", "text": "Пресвятая Троице: Отче наш:"},
  {"id": "cu-sed-0330", "section": "service", "who": "rubric", "text": "И возглашает священник:"},
  {"id": "cu-sed-0331", "section": "service", "who": "priest", "text": "Яко Твое есть Царство:"},
  {"id": "cu-sed-0332", "section": "service", "who": "rubric", "text": "И по амине глаголем тропари, глас 8:"},
  {"id": "cu-sed-0333", "section": "service", "who": "priest", "text": "Видя разбойник Начальника жизни: Слава: Посреде двою разбойнику: И ныне: Агнца и Пастыря, и Спаса мира: Господи помилуй, 40."},
  {"id": "cu-sed-0334", "section": "service", "who": "priest", "text": "Иже на всякое время: Господи помилуй, трижды."},
  {"id": "cu-sed-0335", "section": "service", "who": "priest", "text": "Слава, и ныне: Честнейшую херувим: Именем Господним благослови отче."},
  {"id": "cu-sed-0336", "section": "service", "who": "priest", "text": "Боже ущедри ны:"},
  {"id": "cu-sed-0337", "section": "service", "who": "rubric", "text": "И творим поклоны великия три, глаголюще в себе и предъявленную молитву преподобнаго Ефрема: прочих же 12 не творим. И глаголем молитву:"},
  {"id": "cu-sed-0338", "section": "service", "who": "choir", "text": "Владыко Господи Иисусе Христе Боже наш:"},
  {"id": "cu-sed-0339", "section": "service", "who": "rubric", "text": "И абие начинает лик, емуже прилучится начинати, на глас 8:"},
  {"id": "cu-sed-0340", "section": "service", "who": "choir", "text": "Во Царствии Твоем помяни нас Господи:"},
  {"id": "cu-sed-0341", "section": "service", "who": "rubric", "text": "И поем блаженны со сладкопением и велегласно и косно, в тойже глас:"},
  {"id": "cu-sed-0342", "section": "service", "who": "choir", "text": "Блажени нищии духом, яко тех есть Царство Небесное. Помяни нас Господи, егда приидеши во Царствии Твоем."},
  {"id": "cu-sed-0343", "section": "service", "who": "rubric", "text": "И прочия стихи."},
  {"id": "cu-sed-0344", "section": "service", "who": "choir", "text": "Слава Отцу, и Сыну, и Святому Духу. Помяни нас Господи: И ныне и присно, и во веки веков, аминь. Помяни нас Господи:"},
  {"id": "cu-sed-0345", "section": "service", "who": "rubric", "text": "Таже сошедшеся оба лика, и поем вышшим гласом откровенными главами:"},
  {"id": "cu-sed-0346", "section": "service", "who": "choir", "text": "Помяни нас Господи, егда приидеши во Царствии Твоем. Поклон един."},
  {"id": "cu-sed-0347", "section": "service", "who": "choir", "text": "Помяни нас Владыко, егда приидеши во Царствии Твоем. Поклон един."},
  {"id": "cu-sed-0348", "section": "service", "who": "choir", "text": "Помяни нас Святый, егда приидеши во Царствии Твоем."},
  {"id": "cu-sed-0349", "section": "service", "who": "rubric", "text": "Поклон един. И глаголем:"},
  {"id": "cu-sed-0350", "section": "service", "who": "choir", "text": "Лик небесный поет Тя и глаголет: Стих:"},
  {"id": "cu-sed-0351", "section": "service", "who": "choir", "text": "Приступите к Нему и просветитеся: И паки:"},
  {"id": "cu-sed-0352", "section": "service", "who": "choir", "text": "Лик небесный: Слава: Лик святых ангел и архангел: И ныне: Верую во Единаго Бога: Ослаби, остави: Отче наш:"},
  {"id": "cu-sed-0353", "section": "service", "who": "rubric", "text": "Таже кондак дне и храма. Аще ли храм Христов глаголем прежде храма, таже дне и святаго рядоваго, егоже есть день, иже имать."},
  {"id": "cu-sed-0354", "section": "service", "who": "choir", "text": "Слава: Со святыми упокой Христе: И ныне,"},
  {"id": "cu-sed-0355", "section": "service", "who": "rubric", "text": "храма Богородицы, или:"},
  {"id": "cu-sed-0356", "section": "service", "who": "choir", "text": "Предстательство христиан непостыдное: Господи помилуй, 40."},
  {"id": "cu-sed-0357", "section": "service", "who": "choir", "text": "Слава, и ныне: Честнейшую херувим: Именем Господним благослови отче."},
  {"id": "cu-sed-0358", "section": "service", "who": "rubric", "text": "И глаголет священник:"},
  {"id": "cu-sed-0359", "section": "service", "who": "priest", "text": "Боже ущедри ны:"},
  {"id": "cu-sed-0360", "section": "service", "who": "rubric", "text": "И творим изображенныя поклоны 16 с молитвою святаго Ефрема, якоже предписася."},
  {"id": "cu-sed-0361", "section": "service", "who": "rubric", "text": "Параекклисиарх же поклон сотворив настоятелю, и благословение взем, идет и звонит. Таже начинает предстоятель:"},
  {"id": "cu-sed-0362", "section": "service", "who": "priest", "text": "Приидите поклонимся:"},
  {"id": "cu-sed-0363", "section": "service", "who": "rubric", "text": "трижды, и метания 3. И чтец глаголет псалом:"},
  {"id": "cu-sed-0364", "section": "service", "who": "reader", "text": "Благослови душе моя Господа:"},
  {"id": "cu-sed-0365", "section": "service", "who": "rubric", "text": "тихим и кротким гласом. Иерей же глаголет обычныя молитвы вечерния пред святыми враты. По псалме,"},
  {"id": "cu-sed-0366", "section": "service", "who": "reader", "text": "Слава, и ныне, Аллилуия,"},
  {"id": "cu-sed-0367", "section": "service", "who": "rubric", "text": "трижды, и поклоны 3. И ектения великая. И стихословим кафисму:"},
  {"id": "cu-sed-0368", "section": "service", "who": "choir", "text": "Ко Господу внегда скорбети ми:"},
  {"id": "cu-sed-0369", "section": "service", "who": "rubric", "text": "и по коемждо антифоне,"},
  {"id": "cu-sed-0370", "section": "service", "who": "choir", "text": "Слава, и ныне, Аллилуия,"},
  {"id": "cu-sed-0371", "section": "service", "who": "rubric", "text": "трижды. и метания три."},
  {"id": "cu-sed-0372", "section": "service", "who": "choir", "text": "В ПОНЕДЕЛЬНИК, ВЕЧЕР На"},
  {"id": "cu-sed-0373", "section": "service", "who": "choir", "text": "Господи воззвах,"},
  {"id": "cu-sed-0374", "section": "service", "who": "rubric", "text": "стихиры, поставим стихов 6."},
  {"id": "cu-sed-0375", "section": "service", "who": "choir", "text": "Творение господина Иосифа. Глас 2. Подобен: Вся прейду:"},
  {"id": "cu-sed-0376", "section": "service", "who": "choir", "text": "Всякий грех содеях, всех преидох блудом: / аще восхощу покаятися, не имам слез токи! / Аще леностно и ныне поживу, муце повинен есмь. / Но даждь ми исправление, / едине благий Боже, и помилуй мя."},
  {"id": "cu-sed-0377", "section": "service", "who": "choir", "text": "Подобен:"},
  {"id": "cu-sed-0378", "section": "service", "who": "choir", "text": "Тучи ми подаждь Христе слез, в поста красный день, / яко да восплачу, и отмыю скверну яже от сластей, / и явлюся Тебе очищен, / егда Судие с Небеси имаши приити Господи, / судити человеком, / яко Судия, и Праведный един."},
  {"id": "cu-sed-0379", "section": "service", "who": "choir", "text": "Другий, глас 5. Господина Феодора Студита. Подобен: Преподобне отче:"},
  {"id": "cu-sed-0380", "section": "service", "who": "choir", "text": "Приидите усердно, / твердое оружие поста имуще яко щит, / всякую кознь прелести вражия отвратим вернии. / Не опалимся сладостьми страстей, / ни огня искушений убоимся, / имиже Христос Человеколюбец / почестьми терпения венчает нас. / Темже со дерзновением молящеся, / припадаем зовуще, / просяще мира, и душам нашим велия милости. И в Минеи, 3."},
  {"id": "cu-sed-0381", "section": "service", "who": "choir", "text": "Слава, и ныне, Богородичен."},
  {"id": "cu-sed-0382", "section": "service", "who": "choir", "text": "Свете тихий:"},
  {"id": "cu-sed-0383", "section": "service", "who": "choir", "text": "Таже прокимен, псалом 3, глас 6:"},
  {"id": "cu-sed-0384", "section": "service", "who": "choir", "text": "Господне есть спасение, / и на людех Твоих благословение Твое. Стих:"},
  {"id": "cu-sed-0385", "section": "service", "who": "choir", "text": "Господи, что ся умножиша стужающии ми?"},
  {"id": "cu-sed-0386", "section": "service", "who": "choir", "text": "Бытия чтение. [Глава 1, ст. 1 – 13.]"},
  {"id": "cu-sed-0387", "section": "service", "who": "choir", "text": "В начале сотвори Бог небо и землю. Земля же бе невидима и неустроена, и тьма верху бездны, и Дух Божий ношашеся верху воды. И рече Бог: да будет свет. И бысть свет. И виде Бог свет, яко добро, и разлучи Бог между светом и между тьмою. И нарече Бог свет день, а тму нарече нощь. И бысть вечер, и бысть утро, день един."},
  {"id": "cu-sed-0388", "section": "service", "who": "choir", "text": "И рече Бог: да будет твердь посреде воды, и да будет разлучающи посреде воды и воды. И бысть тако. И сотвори Бог твердь, и разлучи Бог между водою, яже бе под твердию, и между водою, яже бе над твердию. И нарече Бог твердь, небо. И виде Бог, яко добро. И бысть вечер, и бысть утро, день вторый."},
  {"id": "cu-sed-0389", "section": "service", "who": "choir", "text": "И рече Бог: да соберется вода, яже под небесем, в собрание едино, и да явится суша. И бысть тако. И собрася вода, яже под небесем в собрания своя, и явися суша. И нарече Бог сушу, землю, и собрания вод нарече моря. И виде Бог, яко добро."},
  {"id": "cu-sed-0390", "section": "service", "who": "choir", "text": "И рече Бог: да прорастит земля былие травное, сеющее семя по роду и по подобию, и древо плодовитое творящее плод, емуже семя его в нем, по роду на земли, и бысть тако. И изнесе земля былие травное, сеющее семя по роду и по подобию, и древо плодовитое творящее плод, емуже семя его в нем, по роду на земли. И виде Бог, яко добро. И бысть вечер, и бысть утро, день третий."},
  {"id": "cu-sed-0391", "section": "service", "who": "choir", "text": "Прокимен 2, псалом 4, глас 5: Господь услышит мя, внегда воззвати ми к Нему. Стих:"},
  {"id": "cu-sed-0392", "section": "service", "who": "choir", "text": "Внегда призвати ми, услыша мя Бог правды моея."},
  {"id": "cu-sed-0393", "section": "service", "who": "choir", "text": "Притчей чтение. [Глава 1, ст. 1 – 20.]"},
  {"id": "cu-sed-0394", "section": "service", "who": "choir", "text": "Притчи Соломона сына Давидова, иже царствова во Израили. Познати премудрость и наказание, и уразумети словеса мудрости. Прияти же извития словес и разрешения гаданий, уразумети же правду истинную и суд исправляти. Да даст незлобивым коварство, отрочати же юну чувство же и смысл. Сих бо послушав, мудрый премудрее будет, а разумный строительство стяжет. Уразумеет же притчу, и темное слово, речения же премудрых, и гадания. Начало премудрости страх Господень, разум же благ всем творящим его: благочестие же в Бога начало чувства, премудрость же и наказание нечестивии уничижат. Слыши, сыне, наказание отца твоего, и не отрини заветов матере твоея. Венец бо благодатей приимеши на твоем версе и гривну злату о твоей выи. Сыне, да не прельстят тебе мужи нечестивии, ниже да восхощеши, Аще помолят тя, глаголюще: иди с нами, приобщися крове, скрыем же в землю мужа праведна неправедно. Пожрем же его якоже ад жива, и возмем память его от земли. Стяжание его многоценное приимем, исполним же домы наша корыстей. Жребий же твой положи с нами: обще же влагалище стяжем вси, и мешец един да будет всем нам. Не иди в путь с ними: уклони же ногу твою от стезь их: Нозе бо их на зло текут, и скори суть излияти кровь. Не без правды бо простираются мрежи пернатым. Тии бо убийству приобщающеся, сокровищствуют себе злая: разрушение же мужей законопреступных зло. Сии путие суть всех творящих беззаконная: нечестием бо свою душу отъемлют. Премудрость во исходех поется, в стогнах же дерзновение водит."},
  {"id": "cu-sed-0395", "section": "service", "who": "choir", "text": "Сподоби Господи в вечер:"},
  {"id": "cu-sed-0396", "section": "service", "who": "rubric", "text": "И метания 3. Иерей:"},
  {"id": "cu-sed-0397", "section": "service", "who": "priest", "text": "Исполним вечернюю молитву:"},
  {"id": "cu-sed-0398", "section": "service", "who": "rubric", "text": "По возгласе поем оба лика вкупе:"},
  {"id": "cu-sed-0399", "section": "service", "who": "priest", "text": "На стиховне самогласен дне, глас 3:"},
  {"id": "cu-sed-0400", "section": "service", "who": "priest", "text": "Постимся постом приятным, благоугодным Господеви: / истинный пост есть, злых отчуждение, / воздержание языка, ярости отложение, / похотей отлучение, оглаголания, лжи и клятвопреступления. / Сих оскудение, / пост истинный есть, и благоприятный. Стих:"},
  {"id": "cu-sed-0401", "section": "service", "who": "priest", "text": "К Тебе возведох очи мои, живущему на небеси. Се яко очи раб в руку господий своих, яко очи рабыни в руку госпожи своея, тако очи наши ко Господу Богу нашему, / дондеже ущедрит ны."},
  {"id": "cu-sed-0402", "section": "service", "who": "rubric", "text": "И повторяем тойже."},
  {"id": "cu-sed-0403", "section": "service", "who": "rubric", "text": "Таже мученичен. Стих:"},
  {"id": "cu-sed-0404", "section": "service", "who": "priest", "text": "Помилуй нас Господи, помилуй нас, яко по многу исполнихомся уничижения: наипаче наполнися душа наша поношения гобзующих, / и уничижения гордых."},
  {"id": "cu-sed-0405", "section": "service", "who": "priest", "text": "Велия мученик Твоих Христе сила: / во гробех бо лежат, и духи прогоняют, / и упраздниша вражию власть, / верою Троическою подвигшеся о благочестии."},
  {"id": "cu-sed-0406", "section": "service", "who": "priest", "text": "Слава, и ныне, Богородичен: Богородице, предстательство всех молящихся, / дерзаем, Тобою хвалимся, / в Тебе все упование наше есть: / моли Рождшагося из Тебе / о непотребных рабех Твоих."},
  {"id": "cu-sed-0407", "section": "service", "who": "rubric", "text": "Таже творит канонарх обычный поклон в лики, такожде и оба лика."},
  {"id": "cu-sed-0408", "section": "service", "who": "priest", "text": "Ныне отпущаеши:"},
  {"id": "cu-sed-0409", "section": "service", "who": "rubric", "text": "Трисвятое: И метания 3. Священник:"},
  {"id": "cu-sed-0410", "section": "service", "who": "priest", "text": "Яко Твое есть Царство: И по амине:"},
  {"id": "cu-sed-0411", "section": "service", "who": "priest", "text": "Богородице Дево радуйся: Поклон един."},
  {"id": "cu-sed-0412", "section": "service", "who": "priest", "text": "Слава: Крестителю Христов: Поклон един."},
  {"id": "cu-sed-0413", "section": "service", "who": "priest", "text": "И ныне: Молите за ны:"},
  {"id": "cu-sed-0414", "section": "service", "who": "rubric", "text": "Поклон един. Таже,"},
  {"id": "cu-sed-0415", "section": "service", "who": "priest", "text": "Под Твое благоутробие: без поклона."},
  {"id": "cu-sed-0416", "section": "service", "who": "priest", "text": "Господи помилуй,"},
  {"id": "cu-sed-0417", "section": "service", "who": "rubric", "text": "40: кротким гласом."},
  {"id": "cu-sed-0418", "section": "service", "who": "priest", "text": "Слава, и ныне: Честнейшую херувим: Именем Господним благослови отче."},
  {"id": "cu-sed-0419", "section": "service", "who": "priest", "text": "Сый благословен Христос Бог наш: Небесный Царю:"},
  {"id": "cu-sed-0420", "section": "service", "who": "rubric", "text": "И глаголем молитву тайно преподобнаго Ефрема:"},
  {"id": "cu-sed-0421", "section": "service", "who": "priest", "text": "Господи, и Владыко живота моего:"},
  {"id": "cu-sed-0422", "section": "service", "who": "rubric", "text": "И творим 3 великия поклоны, и малых 12. И паки предписанную молитву, и поклон един. Трисвятое."},
  {"id": "cu-sed-0423", "section": "service", "who": "priest", "text": "Господи помилуй,"},
  {"id": "cu-sed-0424", "section": "service", "who": "rubric", "text": "12. И молитва:"},
  {"id": "cu-sed-0425", "section": "service", "who": "priest", "text": "Всесвятая Троице, единосущная державо: Таже,"},
  {"id": "cu-sed-0426", "section": "service", "who": "priest", "text": "Буди имя Господне благословенно от ныне и до века."},
  {"id": "cu-sed-0427", "section": "service", "who": "rubric", "text": "Трижды. И метания 3."},
  {"id": "cu-sed-0428", "section": "service", "who": "priest", "text": "Слава, и ныне: Благословлю Господа на всякое время: Посем,"},
  {"id": "cu-sed-0429", "section": "service", "who": "priest", "text": "Достойно есть:"},
  {"id": "cu-sed-0430", "section": "service", "who": "rubric", "text": "и поклон. Посем другий лик:"},
  {"id": "cu-sed-0431", "section": "service", "who": "choir", "text": "Слава, и ныне: Господи помилуй, трижды."},
  {"id": "cu-sed-0432", "section": "service", "who": "choir", "text": "Благослови."},
  {"id": "cu-sed-0433", "section": "service", "who": "rubric", "text": "И отпуст по обычаю. Егда же поставляем трапезу, глаголем и псалом 144:"},
  {"id": "cu-sed-0434", "section": "service", "who": "choir", "text": "Вознесу Тя Боже мой:"},
  {"id": "cu-sed-0435", "section": "service", "who": "rubric", "text": "И бывает отпуст. Исходяще же в паперть, поем якоже обычай стихиру храма святаго. Глаголются же и от священника обычныя молитвы, и поминает усопшия."},
  {"id": "cu-sed-0436", "section": "service", "who": "rubric", "text": "И бывает совершенный отпуст."},
  {"id": "cu-sed-0437", "section": "service", "who": "rubric", "text": "Сие последование бывает светильничнаго, во всей святей Четыредесятнице, не сущей преждеосвященней: не прияхом бо творити преждеосвященную, даже до среды, за еже поститися по преданию всему братству, могущии же да пребудут постящеся до пятка."},
  {"id": "cu-sed-0438", "section": "service", "who": "rubric", "text": "Святыя же горы устав в первый убо день отнюд не повелевает ясти. Во вторник же, в среду, и в четверток ясти подобает по единой литре хлеба, и воду, и ино ничтоже, разве соли требуя с хлебом."},
  {"id": "cu-sed-0439", "section": "service", "who": "rubric", "text": "Подобает ведати: Яко в лавре преподобнаго отца нашего Саввы, не поем Повечерий в церкви, но в келлиях поем кийждо: тако бо прияхом."},
  {"id": "cu-sed-0440", "section": "service", "who": "rubric", "text": "Во общежитиях же Палестины поются Повечерия сице:"},
  {"id": "cu-sed-0441", "section": "service", "who": "choir", "text": "НА ВЕЛИКОМ ПОВЕЧЕРИИ"},
  {"id": "cu-sed-0442", "section": "service", "who": "rubric", "text": "О часе девятом, входит свещевжигатель, и сотворив поклон предстоятелю отыдет, и биет в било дванадесять. И собираемся вси в церковь, и сотворивше кийждо вчиненыя поклоны, и мало седше, во еже всем, или множайшым собратися: Востав священник от седалища своего и сотворив обычный поклон игумену, творит благословение. И мы начинаем:"},
  {"id": "cu-sed-0443", "section": "service", "who": "priest", "text": "Слава Тебе Боже наш, слава Тебе: Царю Небесный:"},
  {"id": "cu-sed-0444", "section": "service", "who": "rubric", "text": "Трисвятое, и метания 3. Подобне и на"},
  {"id": "cu-sed-0445", "section": "service", "who": "priest", "text": "Приидите поклонимся,"},
  {"id": "cu-sed-0446", "section": "service", "who": "rubric", "text": "метания 3. И абие глаголем псалом 69:"},
  {"id": "cu-sed-0447", "section": "service", "who": "priest", "text": "Боже, в помощь мою вонми:"},
  {"id": "cu-sed-0448", "section": "service", "who": "rubric", "text": "Таже начинаем великий канон, творяще и на части четыре со ирмосом, яко исполнитися ему в четверток вечера. Творение святаго отца нашего Андрея Критскаго, Иерусалимскаго. Творим же на кийждо тропарь метания 3."},
  {"id": "cu-sed-0449", "section": "service", "who": "rubric", "text": "Ирмос:"},
  {"id": "cu-sed-0450", "section": "service", "who": "priest", "text": "Помощник и покровитель / бысть мне во спасение, / Сей мой Бог, и прославлю Его, / Бог отца моего, и вознесу Его: / славно бо прославися. Стих:"},
  {"id": "cu-sed-0451", "section": "service", "who": "priest", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "cu-sed-0452", "section": "service", "who": "choir", "text": "Откуду начну плакати / окаяннаго моего жития деяний? / Кое ли положу начало, Христе, нынешнему рыданию? / Но яко благоутробен, / даждь ми прегрешений оставление."},
  {"id": "cu-sed-0453", "section": "service", "who": "choir", "text": "Гряди окаянная душе, с плотию твоею, / Зиждителю всех исповеждься, / и останися прочее преждняго безсловесия, / и принеси Богу в покаянии слезы."},
  {"id": "cu-sed-0454", "section": "service", "who": "choir", "text": "Первозданнаго Адама преступлению поревновав, / познах себе обнажена от Бога / и присносущнаго Царствия и сладости, / грех ради моих."},
  {"id": "cu-sed-0455", "section": "service", "who": "choir", "text": "Увы мне окаянная душе, / что уподобилася еси первей Еве? / Видела бо еси зле, и уязвилася еси горце, / и коснулася еси древа и вкусила еси дерзостно / безсловесныя снеди."},
  {"id": "cu-sed-0456", "section": "service", "who": "choir", "text": "Вместо Евы чувственныя / мысленная ми бысть Ева, / во плоти страстный помысл, / показуяй сладкая / и вкушаяй присно / горькаго напоения."},
  {"id": "cu-sed-0457", "section": "service", "who": "choir", "text": "Достойно из Едема изгнан бысть, / яко не сохранив едину Твою, Спасе, заповедь Адам: / аз же что постражду, / отметая всегда животная Твоя словеса?"},
  {"id": "cu-sed-0458", "section": "service", "who": "choir", "text": "Слава, Троичен: Пресущная Троице, во Единице покланяемая, / возми бремя от мене тяжкое греховное, / и яко благоутробна, / даждь ми слезы умиления. Богородичен:"},
  {"id": "cu-sed-0459", "section": "service", "who": "choir", "text": "Богородице, надежде и предстательство Тебе поющих, / возми бремя от мене тяжкое греховное, / и яко Владычица Чистая, / кающася приими мя."},
  {"id": "cu-sed-0460", "section": "service", "who": "choir", "text": "Песнь 2. Ирмос:"},
  {"id": "cu-sed-0461", "section": "service", "who": "choir", "text": "Вонми, небо, и возглаголю, / и воспою Христа, / от Девы плотию пришедшаго. (2)"},
  {"id": "cu-sed-0462", "section": "service", "who": "choir", "text": "Вонми небо, и возглаголю, / земле, внушай глас, / кающийся к Богу и воспевающий Его."},
  {"id": "cu-sed-0463", "section": "service", "who": "choir", "text": "Вонми ми, Боже, Спасе мой / милостивным Твоим оком, / и приими мое теплое исповедание."},
  {"id": "cu-sed-0464", "section": "service", "who": "choir", "text": "Согреших паче всех человек, / един согреших Тебе: / но ущедри яко Бог, Спасе, / творение Твое."},
  {"id": "cu-sed-0465", "section": "service", "who": "choir", "text": "Вообразив моих страстей безобразие, / любосластными стремленьми / погубих ума красоту."},
  {"id": "cu-sed-0466", "section": "service", "who": "choir", "text": "Буря мя злых обдержит, / благоутробне Господи: / но яко Петру, / и мне руку простри."},
  {"id": "cu-sed-0467", "section": "service", "who": "choir", "text": "Оскверних плоти моея ризу / и окалях / еже по образу, Спасе, / и по подобию."},
  {"id": "cu-sed-0468", "section": "service", "who": "choir", "text": "Омрачих душевную красоту / страстей сластьми, / и всячески весь ум / персть сотворих."},
  {"id": "cu-sed-0469", "section": "service", "who": "choir", "text": "Раздрах ныне одежду мою первую, / иже ми изтка Зиждитель из начала, / и оттуду лежу наг."},
  {"id": "cu-sed-0470", "section": "service", "who": "choir", "text": "Облекохся в раздранную ризу, / юже изтка ми змий советом, / и стыждуся."},
  {"id": "cu-sed-0471", "section": "service", "who": "choir", "text": "Слезы блудницы, Щедре, / и аз предлагаю: / очисти мя, Спасе, / благоутробием Твоим."},
  {"id": "cu-sed-0472", "section": "service", "who": "choir", "text": "Воззрех на садовную красоту / и прельстихся умом: / и оттуду лежу наг, и срамляюся."},
  {"id": "cu-sed-0473", "section": "service", "who": "choir", "text": "Делаша на хребте моем / вси начальницы страстей, / продолжающе на мя / беззаконие их."},
  {"id": "cu-sed-0474", "section": "service", "who": "choir", "text": "Слава, Троичен: Единаго Тя в триех Лицех, / Бога всех пою, / Отца и Сына и Духа Святаго. Богородичен:"},
  {"id": "cu-sed-0475", "section": "service", "who": "choir", "text": "Пречистая Богородице Дево, / едина Всепетая, / моли прилежно во еже спастися нам."},
  {"id": "cu-sed-0476", "section": "service", "who": "choir", "text": "Песнь 3. Ирмос:"},
  {"id": "cu-sed-0477", "section": "service", "who": "choir", "text": "На недвижимом, Христе, камени заповедий Твоих, / утверди мое помышление. (2)"},
  {"id": "cu-sed-0478", "section": "service", "who": "choir", "text": "Огнь от Господа иногда / Господь одождив, / землю Содомскую / прежде попали."},
  {"id": "cu-sed-0479", "section": "service", "who": "choir", "text": "На горе спасайся, душе, / якоже Лот оный, / и в Сигор угонзай."},
  {"id": "cu-sed-0480", "section": "service", "who": "choir", "text": "Бегай запаления, о душе, / бегай Содомскаго горения, / бегай тления Божественнаго пламене."},
  {"id": "cu-sed-0481", "section": "service", "who": "choir", "text": "Согреших Тебе един аз, / согреших паче всех, Христе Спасе, / да не презриши мене."},
  {"id": "cu-sed-0482", "section": "service", "who": "choir", "text": "Ты еси Пастырь добрый, / взыщи мене агнца, / и заблуждшаго да не презриши мене."},
  {"id": "cu-sed-0483", "section": "service", "who": "choir", "text": "Ты еси сладкий, Иисусе, / Ты еси Создателю мой: / в Тебе, Спасе, оправдаюся."},
  {"id": "cu-sed-0484", "section": "service", "who": "choir", "text": "Исповедаюся Тебе, Спасе: / согреших, согреших Ти: / но ослаби, остави ми, / яко благоутробен."},
  {"id": "cu-sed-0485", "section": "service", "who": "choir", "text": "Слава, Троичен: О Троице Единице Боже! / Спаси нас от прелести, / и искушений, и обстояний. Богородичен:"},
  {"id": "cu-sed-0486", "section": "service", "who": "choir", "text": "Радуйся, Богоприятная утробо, / радуйся, престоле Господень, / радуйся, Мати Жизни нашея."},
  {"id": "cu-sed-0487", "section": "service", "who": "choir", "text": "Песнь 4. Ирмос:"},
  {"id": "cu-sed-0488", "section": "service", "who": "choir", "text": "Услыша пророк / пришествие Твое, Господи, и убояся, / яко хощеши от Девы родитися / и человеком явитися, и глаголаше: / услышах слух Твой и убояхся, / слава силе Твоей, Господи. (2)"},
  {"id": "cu-sed-0489", "section": "service", "who": "choir", "text": "Дел Твоих да не презриши, / создания Твоего да не оставиши, Правосуде, / аще и един согреших, яко человек, / паче всякаго человека, Человеколюбче, / но имаши, яко Господь всех, / власть оставляти грехи."},
  {"id": "cu-sed-0490", "section": "service", "who": "choir", "text": "Приближается, душе, конец, приближается, / и нерадиши, ни готовишися: / время сокращается, востани, близ при дверех Судия есть: / яко соние, яко цвет, время жития течет: / что всуе мятемся?"},
  {"id": "cu-sed-0491", "section": "service", "who": "choir", "text": "Воспряни, о душе моя, / деяния твоя, яже соделала еси, помышляй, / и сия пред лице твое принеси, / и капли испусти слез твоих: / рцы со дерзновением деяния и помышления Христу, / и оправдайся."},
  {"id": "cu-sed-0492", "section": "service", "who": "choir", "text": "Не бысть в житии греха, ни деяния, ни злобы, / еяже аз, Спасе, не согреших / умом и словом, и произволением / и предложением, и мыслию, и деянием согрешив, / яко ин никтоже когда."},
  {"id": "cu-sed-0493", "section": "service", "who": "choir", "text": "Отсюду и осужден бых, / отсюду препрен бых аз окаянный от своея совести, / еяже ничтоже в мире нужнейше: / Судие Избавителю мой, и ведче, / пощади и избави, и спаси мя раба Твоего."},
  {"id": "cu-sed-0494", "section": "service", "who": "choir", "text": "Лествица, юже виде древле / великий в патриарсех, / указание есть душе моя, / деятельнаго восхождения, разумнаго возшествия: / аще хощеши убо, деянием, и разумом, / и зрением пожити, обновися."},
  {"id": "cu-sed-0495", "section": "service", "who": "choir", "text": "Зной дневный претерпе / лишения ради патриарх, / и мраз нощный понесе, / на всяк день снабдения творя, / пасый, труждаяйся, работаяй, / да две жене сочетает."},
  {"id": "cu-sed-0496", "section": "service", "who": "choir", "text": "Жены ми две разумей, / деяние же и разум в зрении, / Лию убо деяние, яко многочадную: / Рахиль же разум, яко многотрудную: / ибо кроме трудов, ни деяние, ни зрение душе, исправится."},
  {"id": "cu-sed-0497", "section": "service", "who": "choir", "text": "Слава, Троичен: Нераздельное Существом, / неслитное Лицы / богословлю Тя, Троическое Едино Божество, / яко единоцарственное и сопрестольное, / вопию Ти песнь великую, / в вышних трегубо песнословимую. Богородичен:"},
  {"id": "cu-sed-0498", "section": "service", "who": "choir", "text": "И раждаеши и девствуеши, / и пребываеши обоюду естеством Дева: / Рождейся обновляет законы естества, / утроба же раждает, не раждающая. / Бог идеже хощет, побеждается естества чин: / творит бо елика хощет."},
  {"id": "cu-sed-0499", "section": "service", "who": "choir", "text": "Песнь 5. Ирмос:"},
  {"id": "cu-sed-0500", "section": "service", "who": "choir", "text": "От нощи утренююща, / Человеколюбче, просвети, молюся, / и настави и мене на повеления Твоя, / и научи мя, Спасе, / творити волю Твою. (2)"},
  {"id": "cu-sed-0501", "section": "service", "who": "choir", "text": "В нощи житие мое преидох присно, / тьма бо бысть и глубока мне мгла, нощь греха, / но яко дне сына Спасе покажи мя."},
  {"id": "cu-sed-0502", "section": "service", "who": "choir", "text": "Рувима подражая окаянный аз, / содеях беззаконный и законопреступный совет на Бога Вышняго, / осквернив ложе мое, яко отчее он."},
  {"id": "cu-sed-0503", "section": "service", "who": "choir", "text": "Исповедаюся Тебе Христе Царю, / согреших, согреших, / яко прежде Иосифа братия продавшии, / чистоты плод и целомудрия."},
  {"id": "cu-sed-0504", "section": "service", "who": "choir", "text": "От сродников праведная душа связася, / продася в работу сладкий, / во образ Господень: / ты же вся душе, продалася еси / злыми твоими."},
  {"id": "cu-sed-0505", "section": "service", "who": "choir", "text": "Иосифа праведнаго и целомудреннаго ума / подражай окаянная, и неискусная душе, / и не оскверняйся безсловесными стремленьми / присно беззаконнующи."},
  {"id": "cu-sed-0506", "section": "service", "who": "choir", "text": "Аще и в рове поживе иногда Иосиф, / Владыко Господи, / но во образ погребения и востания Твоего: / аз же что Тебе когда сицевое принесу?"},
  {"id": "cu-sed-0507", "section": "service", "who": "choir", "text": "Слава, Троичен: Тя Троице славим, Единаго Бога: / Свят, Свят, Свят еси Отче, Сыне и Душе, / простое Существо, / Единице присно покланяемая. Богородичен:"},
  {"id": "cu-sed-0508", "section": "service", "who": "choir", "text": "Из Тебе облечеся в мое смешение, / нетленная, безмужная Мати Дево, / Бог создавый веки, / и соедини Себе человеческое естество."},
  {"id": "cu-sed-0509", "section": "service", "who": "choir", "text": "Песнь 6. Ирмос:"},
  {"id": "cu-sed-0510", "section": "service", "who": "choir", "text": "Возопих всем сердцем моим / к щедрому Богу, / и услыша мя от ада преисподняго, / и возведе от тли живот мой. (2)"},
  {"id": "cu-sed-0511", "section": "service", "who": "choir", "text": "Слезы Спасе очию моею, / и из глубины воздыхания / чисте приношу, вопиющу сердцу: / Боже, согреших Ти / очисти мя."},
  {"id": "cu-sed-0512", "section": "service", "who": "choir", "text": "Уклонилася еси душе, от Господа твоего, / якоже Дафан и Авирон: / но пощади, воззови из ада преисподняго, / да не пропасть земная тебе покрыет."},
  {"id": "cu-sed-0513", "section": "service", "who": "choir", "text": "Яко юница душе разсвирепевшая, / уподобилася еси Ефрему, / яко серна от тенет сохрани житие, / вперивши деянием ум, и зрением."},
  {"id": "cu-sed-0514", "section": "service", "who": "choir", "text": "Рука нас Моисеова да уверит душе, / како может Бог прокаженное житие / убелити, и очистити: / и не отчайся сама себе, / аще и прокаженна еси."},
  {"id": "cu-sed-0515", "section": "service", "who": "choir", "text": "Слава, Троичен: Троица есмь проста, нераздельна, / раздельна Личне, / и Единица есмь Естеством соединена, / Отец глаголет, и Сын, и Божественный Дух. Богородичен:"},
  {"id": "cu-sed-0516", "section": "service", "who": "choir", "text": "Утроба Твоя Бога нам роди, / воображена по нам: / Егоже яко Создателя всех, моли Богородице, / да молитвами Твоими оправдимся."},
  {"id": "cu-sed-0517", "section": "service", "who": "choir", "text": "Господи, помилуй. (3)"},
  {"id": "cu-sed-0518", "section": "service", "who": "choir", "text": "Слава, и ныне:"},
  {"id": "cu-sed-0519", "section": "service", "who": "choir", "text": "Кондак: Душе моя, душе моя, востани, что спиши? / Конец приближается, и имаши смутитися. / Воспряни убо, да пощадит тя Христос Бог, / везде сый и вся исполняяй."},
  {"id": "cu-sed-0520", "section": "service", "who": "choir", "text": "Песнь 7. Ирмос:"},
  {"id": "cu-sed-0521", "section": "service", "who": "choir", "text": "Согрешихом, беззаконновахом, / неправдовахом пред Тобою, / ниже соблюдохом, ниже сотворихом, / якоже заповедал еси нам; / но не предаждь нас до конца, / отцев Боже. (2)"},
  {"id": "cu-sed-0522", "section": "service", "who": "choir", "text": "Согреших, беззаконновах, / и отвергох заповедь Твою, / яко во гресех произведохся / и приложих язвам струпы себе: / но Сам мя помилуй, / яко Благоутробен, отцев Боже."},
  {"id": "cu-sed-0523", "section": "service", "who": "choir", "text": "Тайная сердца моего / исповедах Тебе Судии моему, / виждь мое смирение, / виждь и скорбь мою, / и вонми суду моему ныне, / и Сам мя помилуй, яко Благоутробен, / отцев Боже."},
  {"id": "cu-sed-0524", "section": "service", "who": "choir", "text": "Саул иногда яко погуби отца своего душе ослята, / внезапу царство обрете к прослутию, / но блюди, не забывай себе, / скотския похоти твоя / произволивши паче Царства Христова."},
  {"id": "cu-sed-0525", "section": "service", "who": "choir", "text": "Давид иногда Богоотец, / аще и согреши сугубо душе моя, / стрелою убо устрелен быв прелюбодейства, / копием же пленен быв убийства томлением, / но ты сама тяжчайшими делы недугуеши, / самохотными стремленьми."},
  {"id": "cu-sed-0526", "section": "service", "who": "choir", "text": "Совокупи убо Давид иногда беззаконию беззаконие: / убийству же любодейство растворив, / покаяние сугубое показа абие: / но сама ты лукавнейшая душе соделала еси, / не покаявшися Богу."},
  {"id": "cu-sed-0527", "section": "service", "who": "choir", "text": "Давид иногда вообрази, / списав яко на иконе песнь, / еюже деяние обличает, еже содея, зовый: / помилуй мя. Тебе бо Единому согреших всех Богу, / Сам очисти мя."},
  {"id": "cu-sed-0528", "section": "service", "who": "choir", "text": "Слава, Троичен: Троице простая, нераздельная, / единосущная, и Естество едино, / Светове, и Свет, и Свята три, и едино Свято / поется Бог Троица: / но воспой, прослави, Живот и Животы, душе, / всех Бога. Богородичен:"},
  {"id": "cu-sed-0529", "section": "service", "who": "choir", "text": "Поем Тя, благословим Тя, / покланяемся Ти Богородительнице, / яко нераздельныя Троицы породила еси единаго Христа Бога / и Сама отверзла еси нам / сущим на земли небесная."},
  {"id": "cu-sed-0530", "section": "service", "who": "choir", "text": "Песнь 8. Ирмос:"},
  {"id": "cu-sed-0531", "section": "service", "who": "choir", "text": "Егоже воинства Небесная славят, / и трепещут Херувими и Серафими, / всяко дыхание и тварь, / пойте, благословите / и превозносите во вся веки. (2)"},
  {"id": "cu-sed-0532", "section": "service", "who": "choir", "text": "Согрешивша Спасе помилуй, / воздвигни мой ум ко обращению, / приими мя кающагося, ущедри вопиюща: / согреших Ти, спаси, / беззаконновах, помилуй мя."},
  {"id": "cu-sed-0533", "section": "service", "who": "choir", "text": "Колесничник Илия, / колесницею добродетелей вшед, / яко на небеса, ношашеся / превыше иногда от земных: / сего убо душе моя, восход помышляй."},
  {"id": "cu-sed-0534", "section": "service", "who": "choir", "text": "Елиссей иногда прием милоть Илиину, / прият сугубую благодать от Бога: / ты же о душе моя, сея не причастилася еси благодати / за невоздержание."},
  {"id": "cu-sed-0535", "section": "service", "who": "choir", "text": "Иорданова струя первее, милотию Илииною / Елиссеем, ста сюду и сюду: / ты же, о душе моя, сея не причастилася еси благодати / за невоздержание."},
  {"id": "cu-sed-0536", "section": "service", "who": "choir", "text": "Соманитида иногда / праведнаго учреди, о душе, нравом благим: / ты же не ввела еси в дом, / ни странна, ни путника. / Темже чертога изринешися вон, рыдающи."},
  {"id": "cu-sed-0537", "section": "service", "who": "choir", "text": "Гиезиев подражала еси окаянная / разум скверный всегда душе, / егоже сребролюбие отложи поне на старость: / бегай геенскаго огня, / отступивши злых твоих."},
  {"id": "cu-sed-0538", "section": "service", "who": "choir", "text": "Слава, Троичен: Безначальне Отче, Сыне собезначальне, / Утешителю Благий, Душе Правый: / Слова Божия Родителю, / Отца безначальна Слове, / Душе живый и зиждай, / Троице Единице помилуй мя. Богородичен:"},
  {"id": "cu-sed-0539", "section": "service", "who": "choir", "text": "Яко от оброщения червленицы Пречистая, / умная багряница Еммануилева, / внутрь во чреве Твоем плоть исткася: / темже Богородицу воистинну Тя почитаем."},
  {"id": "cu-sed-0540", "section": "service", "who": "choir", "text": "Песнь 9. Ирмос:"},
  {"id": "cu-sed-0541", "section": "service", "who": "choir", "text": "Безсеменнаго зачатия Рождество несказанное, / Матере безмужныя нетленен Плод, / Божие бо рождение обновляет естества. / Темже Тя вси роди, / яко Богоневестную Матерь, / православно величаем. (2)"},
  {"id": "cu-sed-0542", "section": "service", "who": "choir", "text": "Ум острупися, тело оболезнися, / недугует дух, слово изнеможе, / житие умертвися, конец при дверех. / Темже моя окаянная душе, что сотвориши, / егда приидет Судия испытати твоя?"},
  {"id": "cu-sed-0543", "section": "service", "who": "choir", "text": "Моисеово приведох ти душе, миробытие, / и от того все заветное писание, / поведающее тебе праведныя и неправедныя: / от нихже вторыя, о душе, подражала еси, а не первыя, / в Бога согрешивши."},
  {"id": "cu-sed-0544", "section": "service", "who": "choir", "text": "Закон изнеможе, празднует Евангелие, / писание же все в тебе небрежено бысть, / пророцы изнемогоша, и все праведное слово: / струпи твои, о душе, умножишася, / не сущу врачу исцеляющему тя."},
  {"id": "cu-sed-0545", "section": "service", "who": "choir", "text": "Новаго привожду ти писания указания, / вводящая тя душе, ко умилению: / праведным убо поревнуй, грешных же отвращайся, / и умилостиви Христа молитвами же и пощеньми, / и чистотою, и говением."},
  {"id": "cu-sed-0546", "section": "service", "who": "choir", "text": "Христос вочеловечися, / призвав к покаянию разбойники, и блудницы: / душе покайся, дверь отверзеся Царствия уже, / и предвосхищают е фарисее и мытари / и прелюбодеи кающиися."},
  {"id": "cu-sed-0547", "section": "service", "who": "choir", "text": "Христос вочеловечися, / плоти приобщився ми, / и вся, елика суть естества хотением / исполни греха кроме, / подобие тебе, о душе, / и образ предпоказуя Своего снизхождения."},
  {"id": "cu-sed-0548", "section": "service", "who": "choir", "text": "Христос волхвы спасе, / пастыри созва, / младенец множества показа мученики, / старцы прослави, и старыя вдовицы, / ихже не поревновала еси душе, ни деянием, ни житию, / но горе тебе, внегда будеши судитися."},
  {"id": "cu-sed-0549", "section": "service", "who": "choir", "text": "Постився Господь дний четыредесять в пустыни, / последи взалка, показуя человеческое: / душе, да не разленишися, аще тебе приложится враг, / молитвою же и постом от ног твоих да отразится."},
  {"id": "cu-sed-0550", "section": "service", "who": "choir", "text": "Слава, Троичен: Отца прославим, Сына превознесем, / Божественному Духу верно поклонимся, / Троице нераздельней, Единице по Существу, / яко Свету и Светом, и Животу и Животом, / животворящему и просвещающему концы. Богородичен:"},
  {"id": "cu-sed-0551", "section": "service", "who": "choir", "text": "Град Твой сохраняй / Богородительнице Пречистая, / в Тебе бо сей верно царствуяй, / в Тебе и утверждается, / и Тобою побеждаяй, / побеждает всякое искушение, / и пленяет ратники, / и проходит послушание."},
  {"id": "cu-sed-0552", "section": "service", "who": "choir", "text": "Преподобне отче Андрее, моли Бога о нас. Андрею:"},
  {"id": "cu-sed-0553", "section": "service", "who": "choir", "text": "Андрее честный, и отче треблаженнейший, / пастырю Критский, / не престай моляся о воспевающих тя: / да избавимся вси гнева и скорби, и тления, / и прегрешений безмерных, / чтущии твою память верно."},
  {"id": "cu-sed-0554", "section": "service", "who": "rubric", "text": "Таже поем оба лика ирмос:"},
  {"id": "cu-sed-0555", "section": "service", "who": "choir", "text": "Безсеменнаго зачатия Рождество несказанное, / Матере безмужныя нетленен Плод, / Божие бо рождение обновляет естества. / Темже Тя вси роди, / яко Богоневестную Матерь, / православно величаем."},
  {"id": "cu-sed-0556", "section": "service", "who": "rubric", "text": "По скончании же канона глаголем псалом 4:"},
  {"id": "cu-sed-0557", "section": "service", "who": "choir", "text": "Внегда призвати ми, услыша мя:"},
  {"id": "cu-sed-0558", "section": "service", "who": "rubric", "text": "Такожде и прочыя псалмы Повечерия. На"},
  {"id": "cu-sed-0559", "section": "service", "who": "choir", "text": "Аллилуия"},
  {"id": "cu-sed-0560", "section": "service", "who": "rubric", "text": "метания, 3. И абие начинаем вторую статию:"},
  {"id": "cu-sed-0561", "section": "service", "who": "choir", "text": "К Тебе Господи, воздвигох душу мою:"},
  {"id": "cu-sed-0562", "section": "service", "who": "rubric", "text": "И прочия два псалма, глаголюще в конец сих:"},
  {"id": "cu-sed-0563", "section": "service", "who": "choir", "text": "Аллилуия."},
  {"id": "cu-sed-0564", "section": "service", "who": "rubric", "text": "И творим метания 3. Таже начинает лик, приемый от Вечерни начало:"},
  {"id": "cu-sed-0565", "section": "service", "who": "choir", "text": "С нами Бог:"},
  {"id": "cu-sed-0566", "section": "service", "who": "rubric", "text": "И глаголем сицевыя стихи велегласно, и со сладкопением, глаголющу единому лику, и отвещающу другому. Подобне, и,"},
  {"id": "cu-sed-0567", "section": "service", "who": "choir", "text": "Безплотное естество: Верую же"},
  {"id": "cu-sed-0568", "section": "service", "who": "choir", "text": "во Единаго Бога:"},
  {"id": "cu-sed-0569", "section": "service", "who": "rubric", "text": "низким гласом: Таже наченший лик:"},
  {"id": "cu-sed-0570", "section": "service", "who": "choir", "text": "Пресвятая Владычице Богородице, моли о нас:"},
  {"id": "cu-sed-0571", "section": "service", "who": "rubric", "text": "И творит другий лик поклон. И востающу другому лику и отвещавающу, творит первый лик поклон. Такожде и на прочия молительныя стихи вся. Егда же речем:"},
  {"id": "cu-sed-0572", "section": "service", "who": "choir", "text": "Боже, очисти нас грешных,"},
  {"id": "cu-sed-0573", "section": "service", "who": "rubric", "text": "поем оба лика равно, и поклоны 3. Таже, Трисвятое без поклонов, и глаголем настоящия тропари, на глас 2, яже и поем велегласно и со сладкопением:"},
  {"id": "cu-sed-0574", "section": "service", "who": "choir", "text": "Просвети очи мои Христе Боже: Слава: Заступник души моея: И ныне: Яко не имамы дерзновения:"},
  {"id": "cu-sed-0575", "section": "service", "who": "rubric", "text": "суть же и ины тропари, иже и поются чрез день, на глас 8, сиречь во вторник, и четверток вечера. Суть же сии:"},
  {"id": "cu-sed-0576", "section": "service", "who": "choir", "text": "Невидимых враг моих неусыпание: Стих:"},
  {"id": "cu-sed-0577", "section": "service", "who": "choir", "text": "Призри и услыши мя Господи Боже мой: Яко страшен суд Твой Господи: Слава: Слезы ми даждь Боже: И ныне: Непостыдную Богородице, надежду Твою: Господи помилуй,"},
  {"id": "cu-sed-0578", "section": "service", "who": "rubric", "text": "40. Стих, от священника. И молитва:"},
  {"id": "cu-sed-0579", "section": "service", "who": "priest", "text": "Господи Господи, избавлей нас: таже,"},
  {"id": "cu-sed-0580", "section": "service", "who": "priest", "text": "Приидите поклонимся:"},
  {"id": "cu-sed-0581", "section": "service", "who": "rubric", "text": "трижды. И глаголем 50 и 101 псалом:"},
  {"id": "cu-sed-0582", "section": "service", "who": "priest", "text": "Господи услыши молитву мою: и"},
  {"id": "cu-sed-0583", "section": "service", "who": "priest", "text": "Господи, Вседержителю Боже отец наших:"},
  {"id": "cu-sed-0584", "section": "service", "who": "rubric", "text": "Трисвятое, и метания три. Священник:"},
  {"id": "cu-sed-0585", "section": "service", "who": "priest", "text": "Яко Твое есть Царство:"},
  {"id": "cu-sed-0586", "section": "service", "who": "rubric", "text": "И по амине, глаголем сия тропари скоро, на глас 6:"},
  {"id": "cu-sed-0587", "section": "service", "who": "priest", "text": "Помилуй нас Господи: Слава: Господи, помилуй нас: И ныне: Милосердия двери отверзи нам: Господи помилуй, 40."},
  {"id": "cu-sed-0588", "section": "service", "who": "priest", "text": "Слава, и ныне: Честнейшую херувим: Именем Господним благослови отче."},
  {"id": "cu-sed-0589", "section": "service", "who": "priest", "text": "Молитвами святых отец наших, И молитва:"},
  {"id": "cu-sed-0590", "section": "service", "who": "priest", "text": "Владыко Боже Отче Вседержителю: Приидите поклонимся,"},
  {"id": "cu-sed-0591", "section": "service", "who": "rubric", "text": "трижды. И метания 3."},
  {"id": "cu-sed-0592", "section": "service", "who": "priest", "text": "Боже в помощь мою вонми, и"},
  {"id": "cu-sed-0593", "section": "service", "who": "priest", "text": "Господи, услыши молитву мою, и,"},
  {"id": "cu-sed-0594", "section": "service", "who": "priest", "text": "Слава в вышних Богу: Господи прибежище был еси нам: Сподоби Господи в нощь сию:"},
  {"id": "cu-sed-0595", "section": "service", "who": "rubric", "text": "Таже, Трисвятое."},
  {"id": "cu-sed-0596", "section": "service", "who": "priest", "text": "Пресвятая Троице, помилуй нас: Отче наш:"},
  {"id": "cu-sed-0597", "section": "service", "who": "priest", "text": "Яко Твое есть Царство:"},
  {"id": "cu-sed-0598", "section": "service", "who": "rubric", "text": "Таже поем велегласно и косно, на глас 6:"},
  {"id": "cu-sed-0599", "section": "service", "who": "priest", "text": "Господи сил с нами буди:"},
  {"id": "cu-sed-0600", "section": "service", "who": "rubric", "text": "И отвещает тожде другий лик. И глаголет наченший лик, Стих:"},
  {"id": "cu-sed-0601", "section": "service", "who": "choir", "text": "Хвалите Бога во святых Его, хвалите Его во утвержении силы Его."},
  {"id": "cu-sed-0602", "section": "service", "who": "rubric", "text": "И паки тропарь. Таже тойжде тропарь другий лик на коемждо стихе. По исполнении же пяти стихов, глаголют оба лика вкупе, первый стих и тропарь. Таже начинает наченший лик:"},
  {"id": "cu-sed-0603", "section": "service", "who": "choir", "text": "Слава: Господи аще не быхом: И ныне: Многая множества моих Богородице, прегрешений: Всесвятая Богородице: Все упование мое: Господи помилуй,"},
  {"id": "cu-sed-0604", "section": "service", "who": "rubric", "text": "40. И молитва:"},
  {"id": "cu-sed-0605", "section": "service", "who": "choir", "text": "Иже на всякое время: Господи помилуй, трижды."},
  {"id": "cu-sed-0606", "section": "service", "who": "choir", "text": "Слава, и ныне: Честнейшую херувим: Именем Господним благослови отче. Священник,"},
  {"id": "cu-sed-0607", "section": "service", "who": "choir", "text": "Боже ущедри ны:"},
  {"id": "cu-sed-0608", "section": "service", "who": "rubric", "text": "И творим 16 поклонов, яко обычно, с молитвою святаго Ефрема: и творим косныя за еже уравнятися всем. Таже начинает предстоятель: Трисвятое, и метания 3. По"},
  {"id": "cu-sed-0609", "section": "service", "who": "choir", "text": "Отче наш: Господи помилуй,"},
  {"id": "cu-sed-0610", "section": "service", "who": "rubric", "text": "12. И глаголем молитву:"},
  {"id": "cu-sed-0611", "section": "service", "who": "choir", "text": "Нескверная, неблазная: и,"},
  {"id": "cu-sed-0612", "section": "service", "who": "choir", "text": "И даждь нам Владыко:"},
  {"id": "cu-sed-0613", "section": "service", "who": "rubric", "text": "Подобает ведати: яко вящшии уставы и обычаи повелевают, после,"},
  {"id": "cu-sed-0614", "section": "service", "who": "choir", "text": "И даждь нам Владыко:"},
  {"id": "cu-sed-0615", "section": "service", "who": "rubric", "text": "пасти всем на землю, и глаголати священнику велегласно молитву, яже в Велицей вечерни:"},
  {"id": "cu-sed-0616", "section": "service", "who": "priest", "text": "Владыко Многомилостиве Господи Иисусе Христе Боже наш:"},
  {"id": "cu-sed-0617", "section": "service", "who": "rubric", "text": "И тако сотворив поклон предстоятель на землю, глаголет братиям:"},
  {"id": "cu-sed-0618", "section": "service", "who": "priest", "text": "Благословите отцы святии, простите ми грешному, елика согреших словом, делом, помышлением, и всеми моими чувствы."},
  {"id": "cu-sed-0619", "section": "service", "who": "rubric", "text": "И мы отвещаем:"},
  {"id": "cu-sed-0620", "section": "service", "who": "priest", "text": "Бог да простит ти отче святый:"},
  {"id": "cu-sed-0621", "section": "service", "who": "rubric", "text": "И начинает от леваго лика по чину един и един, творити подобне и просити, и прияти прощение, дондеже скончаются вси. И тако начинает священник глаголати:"},
  {"id": "cu-sed-0622", "section": "service", "who": "priest", "text": "Помолимся о великом господине и отце нашем Святейшем Патриархе Московском и всея Руси [имярек]"},
  {"id": "cu-sed-0623", "section": "service", "who": "priest", "text": ":"},
  {"id": "cu-sed-0624", "section": "service", "who": "rubric", "text": "и прочая, яко в ветхом учинении уставися. И по сих яко обычно, стих от предстоятеля, и к нему от всех подобне поклон, и тако отходим во своя келлии. Сей чин бывает во всю святую Четыредесятницу в Повечериях."},
  {"id": "cu-sed-0625", "section": "service", "who": "rubric", "text": "Ведомо буди, предстоятелю стих глаголющу, мы:"},
  {"id": "cu-sed-0626", "section": "service", "who": "priest", "text": "Благослови,"},
  {"id": "cu-sed-0627", "section": "service", "who": "rubric", "text": "отвещаваем, приемше прощение. Подобает же екклисиарху и сие смотрити прилежно, да егда Повечерия отпущают быти знамению дне, сиречь прежде сомрака. Се убо яко предписася, един день святых постов прилежно испытавше, предложихом любви вашей, количество пения, и в нем воображенныя от святых отцев поклоны, яже несть лепо презирати, ниже великому законоположителю. Количество же дненощных бываемых в церкви поклонов, суть 300, кроме Полунощницы. Прияхом же в Палестине и в своих келлиях коемуждо пети Псалтирь: и могущии убо совершают ю дненощно: ови же трижды в седмице: ови же дважды. Поклоны же творити, елики коемуждо по своей силе предстоятель вообразит."},
];

